# Edit the function files in lib\<Area>\ (areas: Common, Certificates, AdrDps, Payload, Device, Launcher, Operations, Scenario) and run the build script again.
# Load it as text: . ([scriptblock]::Create([IO.File]::ReadAllText(<path>)))   (the kernel cannot run .ps1 files)

# ===== Common ==============================================================================================

function Assert-Az {
    <#
    .SYNOPSIS
    Stops the notebook when the last native command (normally an az call) failed.
    .DESCRIPTION
    The Azure CLI reports a failure through the exit code, not through an exception, so a notebook cell would
    go on after a failed az command. Call this right after the command.
    .PARAMETER What
    What was being done; it becomes the start of the error message.
    .EXAMPLE
    az group create --name $rg --location uksouth -o none
    Assert-Az 'Creazione del resource group'
    #>
    param(
        [Parameter(Mandatory)][string]$What
    )

    # $LASTEXITCODE is set by every native command (az included); non-zero means the command failed.
    # Throwing turns that silent failure into a PowerShell error, which stops the cell.
    if ($LASTEXITCODE -ne 0) {
        throw "$What non riuscito (az exit code $LASTEXITCODE)."
    }
}

function Write-Pem {
    <#
    .SYNOPSIS
    Writes bytes as a PEM file (LF line ends, UTF-8 without BOM).
    .PARAMETER Path
    Output file.
    .PARAMETER Label
    PEM label: 'CERTIFICATE', 'PRIVATE KEY', 'CERTIFICATE REQUEST'...
    .PARAMETER Bytes
    DER bytes to encode.
    #>
    param(
        [string]$Path,
        [string]$Label,
        [byte[]]$Bytes
    )

    # PEM = Base64 of the DER bytes, wrapped at 76 characters, between BEGIN/END lines that carry the label.
    # InsertLineBreaks does the wrapping, but with CRLF on Windows.
    $b64 = [Convert]::ToBase64String($Bytes, [Base64FormattingOptions]::InsertLineBreaks)

    # Normalise to LF: OpenSSL, the Azure CLI and git all read the file the same way on every platform.
    $body = $b64 -replace "`r`n", "`n"
    $pem  = "-----BEGIN $Label-----`n$body`n-----END $Label-----`n"

    # UTF-8 *without* BOM: a BOM in front of "-----BEGIN" makes some PEM parsers reject the file.
    [IO.File]::WriteAllText($Path, $pem, [Text.UTF8Encoding]::new($false))
}

# ===== Certificates ========================================================================================

function Export-AdrCaCertificates {
    <#
    .SYNOPSIS
    Writes the ADR Issuing CA and Root CA certificates, taken from the chain a device received, as PEM files.
    .DESCRIPTION
    The chain issued by ADR to a device (issued-chain.pem) has three certificates: the device, the Issuing CA, the Root CA.
    The two CAs are public, and other services need them to trust the device certificates:
      adr-ica.pem    the Issuing CA alone: what Event Grid wants (the immediate parent of the device certificate)
      adr-root.pem   the Root CA alone
      adr-trust.pem  Issuing CA + Root CA: what the certificate API (api\cert-api.cs) reads
    No private key is involved: nothing here is secret.
    .PARAMETER ChainPath
    A chain file written by Export-IssuedChain (issued-chain.pem), with the three certificates in order.
    .PARAMETER OutDir
    Folder that receives the three files (created if missing).
    .OUTPUTS
    Object with Ica, Root and Trust (paths) and IcaSubject (the name of the Issuing CA).
    #>
    param(
        [Parameter(Mandatory)][string]$ChainPath,
        [Parameter(Mandatory)][string]$OutDir
    )

    # Cut the PEM blocks out of the chain file, in order.
    $blocks = @([regex]::Matches([IO.File]::ReadAllText($ChainPath), '-----BEGIN CERTIFICATE-----.*?-----END CERTIFICATE-----', 'Singleline') |
        ForEach-Object { $_.Value })

    # Device, Issuing CA, Root CA: with fewer than three there is no CA to export.
    if ($blocks.Count -lt 3) {
        throw "The chain $ChainPath has $($blocks.Count) certificate(s): the device, the Issuing CA and the Root CA are expected."
    }

    New-Item -ItemType Directory -Force $OutDir | Out-Null
    $ica   = Join-Path $OutDir 'adr-ica.pem'
    $root  = Join-Path $OutDir 'adr-root.pem'
    $trust = Join-Path $OutDir 'adr-trust.pem'
    $utf8  = [Text.UTF8Encoding]::new($false)
    # No line break after the last -----END CERTIFICATE-----: the Event Grid service answers "must be in valid PEM format" (400) to a
    # PEM that ends with one, and the az command sends the file as it is (seen on 2026-11-22; the same certificate without it is accepted).
    [IO.File]::WriteAllText($ica,   $blocks[1], $utf8)
    [IO.File]::WriteAllText($root,  $blocks[2], $utf8)
    [IO.File]::WriteAllText($trust, $blocks[1] + "`n" + $blocks[2], $utf8)

    # The subject of the Issuing CA, to show in a notebook that it really is the CA of ADR.
    $c = [Security.Cryptography.X509Certificates.X509Certificate2]::CreateFromPem($blocks[1])
    try { $subject = $c.Subject } finally { $c.Dispose() }

    return [pscustomobject]@{ Ica = $ica; Root = $root; Trust = $trust; IcaSubject = $subject }
}

function Export-IssuedChain {
    <#
    .SYNOPSIS
    Writes the certificate chain issued by ADR, taken from a DPS registration response, as PEM files.
    .DESCRIPTION
    Every element is decoded and rewritten as PEM. The preview API does not guarantee order or encoding, so only the
    elements that really are certificates are exported; the others stay in the original JSON.
    .PARAMETER Json
    JSON returned by 'az iot device registration create'.
    .PARAMETER OutDir
    Folder that receives issued-01.pem, issued-02.pem... and issued-chain.pem (all of them in one file).
    .OUTPUTS
    Number of certificates exported.
    #>
    param(
        [Parameter(Mandatory)][string]$Json,
        [Parameter(Mandatory)][string]$OutDir
    )

    $r = $Json | ConvertFrom-Json

    # The CLI sometimes wraps the answer in 'registrationState', sometimes returns it flat: accept both shapes.
    $state = if ($null -ne $r.registrationState) { $r.registrationState } else { $r }

    # PEM text of each exported certificate, joined at the end into issued-chain.pem.
    $parts = @()
    $i = 0

    # @() makes a single element behave like a list, and a missing property like an empty list.
    foreach ($item in @($state.issuedCertificateChain)) {
        $i++
        try {
            # Each element is Base64 of a DER certificate. Parsing it is the proof that it really is one:
            # anything else throws and is skipped (it stays available in dps-registration.json).
            $bytes = [Convert]::FromBase64String([string]$item)
            $c     = [Security.Cryptography.X509Certificates.X509Certificate2]::new($bytes)

            # {0:d2} -> 01, 02, 03: the files sort in the order of the chain.
            $path = Join-Path $OutDir ('issued-{0:d2}.pem' -f $i)

            # RawData is the clean DER encoding, so the PEM is rebuilt from it, not copied from the response.
            Write-Pem -Path $path -Label 'CERTIFICATE' -Bytes $c.RawData
            $parts += [IO.File]::ReadAllText($path)
            $c.Dispose()
        }
        catch {
            Write-Warning "Elemento $i della catena non riconosciuto: resta nel JSON originale."
        }
    }

    # issued-chain.pem = leaf + intermediates + root in one file: with device-key.pem it is the TLS client certificate.
    if ($parts.Count -gt 0) {
        $chainPath = Join-Path $OutDir 'issued-chain.pem'
        [IO.File]::WriteAllText($chainPath, ($parts -join ''), [Text.UTF8Encoding]::new($false))
    }

    return $parts.Count
}

function Get-CertSummary {
    <#
    .SYNOPSIS
    Subject, issuer and expiry of the first certificate in a PEM file (a private key in the file is not read).
    .PARAMETER Path
    PEM file.
    .OUTPUTS
    Object with Subject, Issuer, NotAfter and Days (whole days left).
    #>
    param(
        [Parameter(Mandatory)][string]$Path
    )

    $text = [IO.File]::ReadAllText($Path)

    # Cut out only the first CERTIFICATE block. A file with key + certificate would make CreateFromPem fail
    # (or load the key), and a chain would load only the first one anyway. Singleline lets '.' span the line breaks.
    $m = [regex]::Match($text, '-----BEGIN CERTIFICATE-----.*?-----END CERTIFICATE-----', 'Singleline')
    $c = [Security.Cryptography.X509Certificates.X509Certificate2]::CreateFromPem($m.Value)

    try {
        return [pscustomobject]@{
            Subject  = $c.Subject
            Issuer   = $c.Issuer
            NotAfter = $c.NotAfter
            # Floor of the days left, computed in UTC so the local time zone does not move the result.
            # It becomes negative once the certificate has expired.
            Days     = [int][math]::Floor(($c.NotAfter.ToUniversalTime() - [DateTime]::UtcNow).TotalDays)
        }
    }
    finally {
        # X509Certificate2 holds native handles: always release them.
        $c.Dispose()
    }
}

function New-DemoCsr {
    <#
    .SYNOPSIS
    Creates a device key and a certificate signing request (CSR).
    .DESCRIPTION
    The common name is the registration ID, as ADR requires. The private key never leaves the device folder:
    only the CSR is sent to the service.
    .PARAMETER Cn
    Common name = registration ID of the device.
    .PARAMETER Dir
    Folder that receives device-key.pem and device.csr.pem.
    .OUTPUTS
    Object with Key and Csr (paths).
    #>
    param(
        [Parameter(Mandatory)][string]$Cn,
        [Parameter(Mandatory)][string]$Dir
    )

    New-Item -ItemType Directory -Force $Dir | Out-Null
    $key = Join-Path $Dir 'device-key.pem'
    $csr = Join-Path $Dir 'device.csr.pem'

    # WHAT: a new ECC key pair on curve NIST P-384, the key type ADR requires for the operational certificate.
    # WHY:  the key is generated here, on the "device", so the private part never travels.
    $curve = [Security.Cryptography.ECCurve]::CreateFromFriendlyName('nistP384')
    $ecdsa = [Security.Cryptography.ECDsa]::Create($curve)

    try {
        # HOW: a CertificateRequest bundles subject + public key; the CSR is signed with the matching private key
        # (SHA-384 pairs with P-384). CN = registration ID is how DPS/ADR know whom the certificate is for.
        $req = [Security.Cryptography.X509Certificates.CertificateRequest]::new(
            "CN=$Cn",
            $ecdsa,
            [Security.Cryptography.HashAlgorithmName]::SHA384)

        # PKCS#8 is the standard "PRIVATE KEY" PEM format that the az CLI and OpenSSL read.
        Write-Pem -Path $key -Label 'PRIVATE KEY' -Bytes $ecdsa.ExportPkcs8PrivateKey()

        # Only this file is sent to the service.
        Write-Pem -Path $csr -Label 'CERTIFICATE REQUEST' -Bytes $req.CreateSigningRequest()
    }
    finally {
        # The key is already on disk: free the in-memory copy.
        $ecdsa.Dispose()
    }

    return [pscustomobject]@{ Key = $key; Csr = $csr }
}

function New-DemoLeaf {
    <#
    .SYNOPSIS
    Creates the bootstrap certificate of a device (client authentication) signed by a local CA.
    .DESCRIPTION
    The bootstrap certificate only introduces the device to DPS. The file bootstrap-chain.pem holds the leaf and the CA:
    it is the one to pass to the Azure CLI.
    .PARAMETER CaDir
    Folder of the signing CA (ca.pem, ca-key.pem).
    .PARAMETER Cn
    Common name = registration ID of the device.
    .PARAMETER Dir
    Folder that receives bootstrap-key.pem, bootstrap-cert.pem and bootstrap-chain.pem.
    .PARAMETER Days
    Validity in days (default 30).
    .OUTPUTS
    Object with Cert, Key and Chain (paths).
    #>
    param(
        [Parameter(Mandatory)][string]$CaDir,
        [Parameter(Mandatory)][string]$Cn,
        [Parameter(Mandatory)][string]$Dir,
        [int]$Days = 30
    )

    New-Item -ItemType Directory -Force $Dir | Out-Null

    # Load the CA certificate together with its private key: the certificate is signed with that key.
    $caPemPath = Join-Path $CaDir 'ca.pem'
    $issuer = [Security.Cryptography.X509Certificates.X509Certificate2]::CreateFromPem(
        [IO.File]::ReadAllText($caPemPath),
        [IO.File]::ReadAllText((Join-Path $CaDir 'ca-key.pem')))

    # The device's own key pair (P-384, like every key in the demo).
    $curve = [Security.Cryptography.ECCurve]::CreateFromFriendlyName('nistP384')
    $ecdsa = [Security.Cryptography.ECDsa]::Create($curve)

    try {
        $req = [Security.Cryptography.X509Certificates.CertificateRequest]::new(
            "CN=$Cn",
            $ecdsa,
            [Security.Cryptography.HashAlgorithmName]::SHA384)
        $usage = [Security.Cryptography.X509Certificates.X509KeyUsageFlags]

        # Extensions that make this a *leaf* for client authentication:
        #  - BasicConstraints CA=false: it cannot sign other certificates (critical).
        $req.CertificateExtensions.Add(
            [Security.Cryptography.X509Certificates.X509BasicConstraintsExtension]::new($false, $false, 0, $true))
        #  - KeyUsage DigitalSignature: all TLS client authentication needs (critical).
        $req.CertificateExtensions.Add(
            [Security.Cryptography.X509Certificates.X509KeyUsageExtension]::new($usage::DigitalSignature, $true))
        #  - ExtendedKeyUsage 1.3.6.1.5.5.7.3.2 = clientAuth: the certificate may be presented by a TLS client.
        $eku = [Security.Cryptography.OidCollection]::new()
        [void]$eku.Add([Security.Cryptography.Oid]::new('1.3.6.1.5.5.7.3.2'))
        $req.CertificateExtensions.Add(
            [Security.Cryptography.X509Certificates.X509EnhancedKeyUsageExtension]::new($eku, $false))

        # Random 128-bit serial number. Clearing the top bit keeps it positive (a DER INTEGER is signed).
        $serial = [byte[]]::new(16)
        [Security.Cryptography.RandomNumberGenerator]::Fill($serial)
        $serial[0] = $serial[0] -band 0x7F

        # Valid from 5 minutes ago (tolerates clock skew with the service) until Days from now.
        $leaf = $req.Create(
            $issuer,
            [DateTimeOffset]::UtcNow.AddMinutes(-5),
            [DateTimeOffset]::UtcNow.AddDays($Days),
            $serial)

        $certPath  = Join-Path $Dir 'bootstrap-cert.pem'
        $keyPath   = Join-Path $Dir 'bootstrap-key.pem'
        $chainPath = Join-Path $Dir 'bootstrap-chain.pem'

        Write-Pem -Path $keyPath  -Label 'PRIVATE KEY' -Bytes $ecdsa.ExportPkcs8PrivateKey()
        Write-Pem -Path $certPath -Label 'CERTIFICATE' -Bytes $leaf.RawData

        # The chain file = leaf first, then the CA: this is what the az CLI sends as the client certificate chain,
        # so DPS can find the CA it trusts.
        $chainText = [IO.File]::ReadAllText($certPath) + [IO.File]::ReadAllText($caPemPath)
        [IO.File]::WriteAllText($chainPath, $chainText, [Text.UTF8Encoding]::new($false))

        $leaf.Dispose()
    }
    finally {
        $ecdsa.Dispose()
        $issuer.Dispose()
    }

    return [pscustomobject]@{ Cert = $certPath; Key = $keyPath; Chain = $chainPath }
}

function New-DemoVerificationCert {
    <#
    .SYNOPSIS
    Creates the proof-of-possession certificate DPS asks for when a CA is verified.
    .DESCRIPTION
    The certificate has the DPS verification code as common name and is signed by the CA being verified.
    .PARAMETER CaDir
    Folder of the CA (ca.pem, ca-key.pem).
    .PARAMETER Code
    Verification code generated by DPS.
    .PARAMETER OutPath
    File that receives the certificate (PEM).
    #>
    param(
        [Parameter(Mandatory)][string]$CaDir,
        [Parameter(Mandatory)][string]$Code,
        [Parameter(Mandatory)][string]$OutPath
    )

    # WHY: DPS wants proof that whoever uploads a CA also owns its private key. It gives a random code;
    # we answer with a certificate whose CN is that code, signed by the CA: only the key owner can produce it.
    $issuer = [Security.Cryptography.X509Certificates.X509Certificate2]::CreateFromPem(
        [IO.File]::ReadAllText((Join-Path $CaDir 'ca.pem')),
        [IO.File]::ReadAllText((Join-Path $CaDir 'ca-key.pem')))

    # Throw-away key pair for the verification certificate: nobody needs it afterwards.
    $curve = [Security.Cryptography.ECCurve]::CreateFromFriendlyName('nistP384')
    $ecdsa = [Security.Cryptography.ECDsa]::Create($curve)

    try {
        $req = [Security.Cryptography.X509Certificates.CertificateRequest]::new(
            "CN=$Code",
            $ecdsa,
            [Security.Cryptography.HashAlgorithmName]::SHA384)

        # Random positive 128-bit serial number (top bit cleared).
        $serial = [byte[]]::new(16)
        [Security.Cryptography.RandomNumberGenerator]::Fill($serial)
        $serial[0] = $serial[0] -band 0x7F

        # Short life (2 days): it is only needed for the moment of the verification.
        $cert = $req.Create(
            $issuer,
            [DateTimeOffset]::UtcNow.AddMinutes(-5),
            [DateTimeOffset]::UtcNow.AddDays(2),
            $serial)

        Write-Pem -Path $OutPath -Label 'CERTIFICATE' -Bytes $cert.RawData
        $cert.Dispose()
    }
    finally {
        $ecdsa.Dispose()
        $issuer.Dispose()
    }
}

function New-DpsBootstrapCa {
    <#
    .SYNOPSIS
    Creates the DPS bootstrap CA of a fleet: the CA whose certificates let a device introduce itself to DPS.
    .DESCRIPTION
    It is not the ADR CA. The ADR Issuing CA (a resource of the namespace, key in a managed HSM) issues the operational certificate the device
    uses with the IoT Hub. The bootstrap CA lives on this machine, signs only the bootstrap credential, and DPS trusts it after it has been
    uploaded and verified (proof of possession, Register-DemoDpsCa). There is one per fleet because DPS finds the enrollment group, and so the
    Hub, from the CA that signed the device credential: with a single CA for two fleets it could not choose.
    An existing CA is never regenerated (it may already be verified on DPS, and a new key would no longer match).
    .PARAMETER Group
    The fleet / enrollment group, for example robots or trucks.
    .PARAMETER OutDir
    The output folder of the scenario (Get-DemoConfig .Out); the CA goes in bootstrap-ca-<group> inside it.
    .PARAMETER Days
    Validity in days (default 1825).
    .OUTPUTS
    Object with Cert, Key (paths) and Created ($false when the CA already existed).
    .EXAMPLE
    $ca = New-DpsBootstrapCa -Group robots -OutDir $cfg.Out
    #>
    param(
        [Parameter(Mandatory)][string]$Group,
        [Parameter(Mandatory)][string]$OutDir,
        [int]$Days = 1825
    )

    # A thin wrapper: only the naming convention lives here (CN "DPS Bootstrap CA <group>", folder bootstrap-ca-<group>).
    # The folder name is what Register-DemoDevice and Open-ScenarioDevice look for.
    New-LocalCa -Name "DPS Bootstrap CA $Group" -Dir (Join-Path $OutDir "bootstrap-ca-$Group") -Days $Days
}

function New-LocalCa {
    <#
    .SYNOPSIS
    Creates a local CA (ECC P-384 / SHA-384) in a folder, unless one is already there.
    .DESCRIPTION
    Any CA that lives on this machine: a CA of your own, a local stand-in for the ADR Issuing CA, or (through New-DpsBootstrapCa) the bootstrap CA of a fleet.
    An existing CA is never regenerated: it may already be registered on DPS, and a new key would no longer match.
    The CA is valid from one day ago: a device certificate issued with the simulated clock (which starts a little
    before the CA is created) must not be dated earlier than its issuer, or .NET refuses it
    ("requested notBefore is earlier than issuerCertificate.NotBefore"). The day also covers clock skew with the services.
    .PARAMETER Name
    Common name of the CA.
    .PARAMETER Dir
    Folder that receives ca.pem and ca-key.pem (created if missing).
    .PARAMETER Days
    Validity in days (default 1825).
    .OUTPUTS
    Object with Cert, Key (paths) and Created ($false when the CA already existed).
    #>
    param(
        [Parameter(Mandatory)][string]$Name,
        [Parameter(Mandatory)][string]$Dir,
        [int]$Days = 1825
    )

    New-Item -ItemType Directory -Force $Dir | Out-Null
    $cert = Join-Path $Dir 'ca.pem'
    $key  = Join-Path $Dir 'ca-key.pem'

    # Idempotent: if both files exist, hand them back untouched (Created = $false).
    # Regenerating would silently break a CA that DPS already verified.
    if ((Test-Path $cert) -and (Test-Path $key)) {
        return [pscustomobject]@{ Cert = $cert; Key = $key; Created = $false }
    }

    $curve = [Security.Cryptography.ECCurve]::CreateFromFriendlyName('nistP384')
    $ecdsa = [Security.Cryptography.ECDsa]::Create($curve)

    try {
        $req = [Security.Cryptography.X509Certificates.CertificateRequest]::new(
            "CN=$Name",
            $ecdsa,
            [Security.Cryptography.HashAlgorithmName]::SHA384)
        $usage = [Security.Cryptography.X509Certificates.X509KeyUsageFlags]

        # Extensions that make this a *CA*:
        #  - BasicConstraints CA=true, no path length limit (critical): it may issue certificates.
        $req.CertificateExtensions.Add(
            [Security.Cryptography.X509Certificates.X509BasicConstraintsExtension]::new($true, $false, 0, $true))
        #  - KeyUsage KeyCertSign + CrlSign (critical): it may sign certificates and revocation lists.
        $req.CertificateExtensions.Add(
            [Security.Cryptography.X509Certificates.X509KeyUsageExtension]::new($usage::KeyCertSign -bor $usage::CrlSign, $true))
        #  - SubjectKeyIdentifier: lets a verifier match a child certificate to this CA by key id.
        $req.CertificateExtensions.Add(
            [Security.Cryptography.X509Certificates.X509SubjectKeyIdentifierExtension]::new($req.PublicKey, $false))

        # Self-signed, valid from one day ago (see the description for why).
        $ca = $req.CreateSelfSigned([DateTimeOffset]::UtcNow.AddDays(-1), [DateTimeOffset]::UtcNow.AddDays($Days))

        Write-Pem -Path $key  -Label 'PRIVATE KEY' -Bytes $ecdsa.ExportPkcs8PrivateKey()
        Write-Pem -Path $cert -Label 'CERTIFICATE' -Bytes $ca.RawData
        $ca.Dispose()
    }
    finally {
        $ecdsa.Dispose()
    }

    return [pscustomobject]@{ Cert = $cert; Key = $key; Created = $true }
}

# ===== AdrDps ==============================================================================================

function Initialize-DemoDevice {
    <#
    .SYNOPSIS
    Makes sure a device has an operational certificate issued by ADR: registers it to DPS the first time, reuses it afterwards.
    .DESCRIPTION
    Some notebooks need a device of their own, with a name that says what it is for (eventgrid-sensore-01, api-client-01),
    so that nobody has to wonder why robot-01 shows up in an Event Grid client list or in an API log.
    These devices are not part of the fleet: they live in the CustomDevices section of _scenario.psd1.

    The function does what notebook 02c does for the fleet, but only when it is needed:
      1. looks in <OutDir>\devices\<Id> for a folder that already holds issued-chain.pem; if there is one, it is returned as it is
         (running a notebook twice must not issue a second certificate);
      2. otherwise it calls Register-DemoDevice: key and CSR, bootstrap certificate from the group's CA, registration to DPS,
         the chain issued by ADR written to disk;
      3. writes manufacturer, model and software revision in ADR, so the device is not an anonymous entry in the inventory.
    The device goes to the Hub of its group, like any other device of the group: a real registration, not a simulation.
    Notebook 99 deletes the whole resource group, so nothing needs a cleanup of its own.
    .PARAMETER Device
    Hashtable or object with Id, Group, Manufacturer, Model, SoftwareRevision (an entry of CustomDevices).
    .PARAMETER OutDir
    Base folder of the generated files ($out in the notebooks). The bootstrap CA of the group must be in <OutDir>\bootstrap-ca-<Group> (notebook 02a).
    .PARAMETER DpsName
    Name of the DPS.
    .PARAMETER ResourceGroup
    Resource group of the DPS and of the ADR namespace.
    .PARAMETER Namespace
    Name of the ADR namespace.
    .OUTPUTS
    The path of the device folder: it holds issued-chain.pem and device-key.pem, which is what the other functions read.
    .EXAMPLE
    $dir = Initialize-DemoDevice -Device $d -OutDir $out -DpsName $dps.Name -ResourceGroup $rg -Namespace $adrName
    #>
    param(
        [Parameter(Mandatory)]$Device,
        [Parameter(Mandatory)][string]$OutDir,
        [Parameter(Mandatory)][string]$DpsName,
        [Parameter(Mandatory)][string]$ResourceGroup,
        [Parameter(Mandatory)][string]$Namespace
    )

    # A folder counts only if the chain is in it: a registration that stopped halfway leaves a folder without it.
    $latest = Get-ChildItem (Join-Path $OutDir "devices\$($Device.Id)") -Directory -ErrorAction SilentlyContinue |
        Where-Object { Test-Path (Join-Path $_.FullName 'issued-chain.pem') } |
        Sort-Object Name |
        Select-Object -Last 1

    if ($latest) {
        Write-Host "[$($Device.Id)] ha gia' un certificato di ADR: lo riuso, non lo registro di nuovo."
        return $latest.FullName
    }

    $registration = Register-DemoDevice `
        -Device $Device `
        -OutDir $OutDir `
        -DpsName $DpsName `
        -ResourceGroup $ResourceGroup

    # The registration created the device in ADR with no properties: describe it, as notebook 02c does for the fleet.
    az iot adr ns device update `
        --name $Device.Id `
        --namespace $Namespace `
        --resource-group $ResourceGroup `
        --manufacturer $Device.Manufacturer `
        --model $Device.Model `
        --software-revision $Device.SoftwareRevision `
        -o none `
        --only-show-errors
    Assert-Az "Proprieta' del device $($Device.Id)"

    return $registration.Cartella
}

function New-MqttConnectPacket {
    <#
    .SYNOPSIS
    Builds the bytes of an MQTT 3.1.1 CONNECT packet.
    .DESCRIPTION
    CONNECT is the first packet a client sends to an MQTT broker. The broker answers with CONNACK: a return code of 0 means
    "accepted". This is all that is needed to prove that a broker accepts a certificate, so there is no MQTT library:
    the packet is small and fixed.
    Layout: fixed header (type 1, remaining length) + protocol name "MQTT" + level 4 + flags + keep alive + client id + user name.
    .PARAMETER ClientId
    The client id (text).
    .PARAMETER Username
    The user name. Event Grid reads the client authentication name from here.
    .OUTPUTS
    The packet as byte[].
    #>
    param(
        [Parameter(Mandatory)][string]$ClientId,
        [Parameter(Mandatory)][string]$Username
    )

    $utf8 = [Text.UTF8Encoding]::new($false)
    $body = [System.Collections.Generic.List[byte]]::new()

    $body.AddRange([byte[]](0x00, 0x04, 0x4D, 0x51, 0x54, 0x54))   # protocol name: length 4, "MQTT"
    $body.Add(0x04)                                                 # protocol level 4 = MQTT 3.1.1
    $body.Add(0x82)                                                 # flags: user name present (0x80) + clean session (0x02)
    $body.AddRange([byte[]](0x00, 0x3C))                            # keep alive: 60 seconds

    # Client id and user name: each is a text with a 2-byte length in front.
    foreach ($text in $ClientId, $Username) {
        $bytes = $utf8.GetBytes($text)
        $body.Add([byte]($bytes.Length -shr 8))
        $body.Add([byte]($bytes.Length -band 0xFF))
        $body.AddRange($bytes)
    }

    # The length is written in one byte here: enough for short names, and the function says so when it is not.
    if ($body.Count -gt 127) {
        throw 'ClientId and Username are too long for this simple encoder (the packet must stay under 128 bytes after the header).'
    }

    $packet = [System.Collections.Generic.List[byte]]::new()
    $packet.Add(0x10)                 # packet type 1 (CONNECT), no flags
    $packet.Add([byte]$body.Count)    # remaining length
    $packet.AddRange($body)

    # The comma keeps the array as one object: without it PowerShell would unroll the bytes into the output.
    return , $packet.ToArray()
}

function Register-DemoDevice {
    <#
    .SYNOPSIS
    Registers one device to DPS and collects the operational certificate issued by ADR.
    .DESCRIPTION
    In the demo this one machine plays three roles: the factory that provisions the device, the device itself, and the operator.
    The steps, with the role that does each one in real life:

      1. DEVICE   Generates an ECC P-384 key (device-key.pem) and a certificate request (CSR, device.csr.pem) with CN = registration ID.
                  The private key is born here and never leaves the device.
      2. FACTORY  Signs a bootstrap certificate for the device with the private key of the fleet's bootstrap CA (bootstrap-ca-<group>\ca-key.pem),
                  valid 30 days, and writes bootstrap-key.pem, bootstrap-cert.pem and bootstrap-chain.pem (certificate + CA).
                  In production the CA key stays with whoever provisions the devices (a vault or an HSM) and only the result goes on the device.
      3. DEVICE   Registers to DPS: the bootstrap certificate authenticates it (DPS trusts the bootstrap CA, uploaded and verified before),
                  and the CSR asks for the operational certificate. DPS finds the enrollment group from the CA, assigns the Hub, forwards the CSR to ADR.
                  The answer is saved as dps-registration.json.
      4. DEVICE   Writes the chain ADR issued: issued-01.pem (the device), issued-02.pem (Issuing CA), issued-03.pem (Root CA) and issued-chain.pem (all three).
                  With device-key.pem, issued-chain.pem is the client certificate used with the IoT Hub.

    What is secret: the private key of the bootstrap CA (ca-key.pem), bootstrap-key.pem and device-key.pem. Everything else is public.
    Where it belongs in production (good practice, not something the demo does):
      - ca-key.pem: never on the device; a vault or HSM on the provisioning side.
      - bootstrap-key.pem, bootstrap-cert.pem, bootstrap-chain.pem: loaded on the device when it is produced, in protected storage.
      - device-key.pem: generated and kept on the device (TPM or secure element), never exported.
      - ca.pem (public part of the bootstrap CA): uploaded to DPS and verified; the device does not need it.
      - issued-chain.pem: received by the device from DPS and kept with its key; it is public.
    In the demo all of it is on one disk, in a time-stamped folder of the device. That folder holds private keys: never publish it.
    The fleet CA is expected in <OutDir>\bootstrap-ca-<Group>.
    .PARAMETER Device
    Hashtable or object with Id (registration ID) and Group (fleet, e.g. robots).
    .PARAMETER OutDir
    Base folder of the generated files.
    .PARAMETER DpsName
    Name of the DPS.
    .PARAMETER ResourceGroup
    Resource group of the DPS.
    .OUTPUTS
    Object with Device, Gruppo, Hub (assigned), Stato, Catena (certificates issued) and Cartella.
    .NOTES
    Replaces the function that used to be defined inside notebook 02, which read $out, $dps and $rg from the notebook.
    The call in the notebook must pass them explicitly.
    #>
    param(
        [Parameter(Mandatory)]$Device,
        [Parameter(Mandatory)][string]$OutDir,
        [Parameter(Mandatory)][string]$DpsName,
        [Parameter(Mandatory)][string]$ResourceGroup
    )

    # One time-stamped folder per registration: a second run never overwrites the files of the first.
    $dir   = Join-Path $OutDir "devices\$($Device.Id)\$(Get-Date -Format 'yyyyMMdd-HHmmss')"
    # The bootstrap CA of the device's fleet (created by New-DpsBootstrapCa).
    $caDir = Join-Path $OutDir "bootstrap-ca-$($Device.Group)"

    # Step 1 (device): key + CSR. Only the CSR will be sent.
    Write-Host "[$($Device.Id)] 1. chiave ECC P-384 e CSR con CN = registration ID"
    $csr = New-DemoCsr -Cn $Device.Id -Dir $dir

    # Step 2 (factory): the bootstrap credential, signed by the fleet CA. 30 days is enough for one demo run.
    Write-Host "[$($Device.Id)] 2. certificato di bootstrap firmato dalla CA della flotta (leaf + CA nel file di catena)"
    $boot = New-DemoLeaf -CaDir $caDir -Cn $Device.Id -Dir $dir -Days 30

    # Step 3 (device): one call does it all. The bootstrap chain + key authenticate the TLS connection to DPS
    # (DPS recognises the fleet from the CA); the CSR asks for the operational certificate.
    # --auth-type login: the control-plane calls use the signed-in az user, not a shared key.
    # --timeout 120: ADR issues the certificate synchronously and it can take a while.
    Write-Host "[$($Device.Id)] 3. registrazione a DPS: il certificato di bootstrap autentica, la CSR chiede il certificato operativo"
    $json = az iot device registration create `
        --dps-name $DpsName `
        --resource-group $ResourceGroup `
        --registration-id $Device.Id `
        --certificate-file-path $boot.Chain `
        --key-file-path $boot.Key `
        --auth-type login `
        --csr $csr.Csr `
        --timeout 120 `
        -o json `
        --only-show-errors
    Assert-Az "Registrazione di $($Device.Id)"

    # az returns the JSON as an array of lines: join it back into one text and keep it as evidence.
    $json = $json -join "`n"
    [IO.File]::WriteAllText((Join-Path $dir 'dps-registration.json'), $json, [Text.UTF8Encoding]::new($false))

    # Step 4 (device): split the issued chain into issued-NN.pem files and issued-chain.pem.
    $state = ($json | ConvertFrom-Json).registrationState
    $count = Export-IssuedChain -Json $json -OutDir $dir
    Write-Host "[$($Device.Id)] 4. Hub assegnato: $($state.assignedHub) | certificati nella catena emessa: $count"

    [pscustomobject]@{
        Device   = $Device.Id
        Gruppo   = $Device.Group
        Hub      = $state.assignedHub
        Stato    = $state.status
        Catena   = $count
        Cartella = $dir
    }
}

function Register-DemoDpsCa {
    <#
    .SYNOPSIS
    Uploads a CA to DPS and VERIFIES it (proof of possession).
    .DESCRIPTION
    An enrollment group accepts devices only if it references a verified CA (--root-ca-name): with --certificate-path DPS
    answers 401002 Invalid certificate. Safe to run again: a CA that is already verified is left alone.
    .PARAMETER DpsName
    Name of the DPS.
    .PARAMETER Rg
    Resource group.
    .PARAMETER Name
    Name of the certificate resource on DPS (for example pcert-iot26-dev-robots).
    .PARAMETER CaDir
    Folder of the local CA (ca.pem, ca-key.pem); verification.pem is written there.
    #>
    param(
        [Parameter(Mandatory)][string]$DpsName,
        [Parameter(Mandatory)][string]$Rg,
        [Parameter(Mandatory)][string]$Name,
        [Parameter(Mandatory)][string]$CaDir
    )

    # 1) Is the CA already there, and verified? "show" fails (non-zero exit code) when the resource does not exist.
    #    The -match 'rue' accepts both "True" and "true", whatever the CLI prints.
    $verified = az iot dps certificate show `
        --dps-name $DpsName `
        --resource-group $Rg `
        --certificate-name $Name `
        --query properties.isVerified `
        -o tsv `
        --only-show-errors 2>$null

    if ($LASTEXITCODE -eq 0 -and "$verified" -match 'rue') {
        Write-Host "  CA '$Name' gia' verificata su DPS." -ForegroundColor Green
        return
    }

    # 2) Not there yet: upload the public part (ca.pem). If it exists but is not verified, skip the upload.
    if ($LASTEXITCODE -ne 0) {
        az iot dps certificate create `
            --dps-name $DpsName `
            --resource-group $Rg `
            --certificate-name $Name `
            --path (Join-Path $CaDir 'ca.pem') `
            --only-show-errors `
            -o none
        Assert-Az "Caricamento della CA '$Name'"
    }

    # 3) Ask DPS for the verification code.
    # A CA that has just been uploaded is not always ready: the first request for the code returned nothing (2026-11-16, real DPS).
    # So up to 6 attempts, re-reading the etag each time. The code is a long alphanumeric line; warnings and errors contain spaces,
    # so they can never be taken for the code and end up in the CN of the verification certificate. The last answer is kept for the error message.
    $code   = $null
    $answer = ''
    for ($try = 1; $try -le 6 -and -not $code; $try++) {
        # The etag is the version of the resource: DPS refuses the call if it is not the current one.
        $etag = az iot dps certificate show `
            --dps-name $DpsName `
            --resource-group $Rg `
            --certificate-name $Name `
            --query etag `
            -o tsv `
            --only-show-errors 2>$null

        # 2>&1: warnings and errors come back in the same output, so they can be shown if the code never arrives.
        $raw = az iot dps certificate generate-verification-code `
            --dps-name $DpsName `
            --resource-group $Rg `
            --certificate-name $Name `
            --etag $etag `
            --query properties.verificationCode `
            -o tsv `
            --only-show-errors 2>&1

        # Trim every line and drop the empty ones, then keep the last one that looks like a code.
        $lines = @($raw) | ForEach-Object { "$_".Trim() } | Where-Object { $_ }
        $code  = $lines | Where-Object { $_ -match '^[0-9A-Za-z]{16,}$' } | Select-Object -Last 1

        if (-not $code) {
            $answer = ($lines | Select-Object -First 3) -join ' | '
            Write-Host "  codice di verifica non ancora disponibile ($try/6)..." -ForegroundColor DarkGray
            Start-Sleep -Seconds 5
        }
    }
    if (-not $code) {
        throw "Codice di verifica non ricevuto per '$Name'. Risposta: $answer"
    }
    Write-Host "  codice di verifica DPS: $code" -ForegroundColor DarkGray

    # 4) Proof of possession: a certificate with CN = code, signed with the CA's private key.
    $verification = Join-Path $CaDir 'verification.pem'
    New-DemoVerificationCert -CaDir $CaDir -Code $code -OutPath $verification

    # 5) Send it. The etag is read again: generating the code changed the version of the resource.
    $etag = az iot dps certificate show `
        --dps-name $DpsName `
        --resource-group $Rg `
        --certificate-name $Name `
        --query etag `
        -o tsv `
        --only-show-errors
    az iot dps certificate verify `
        --dps-name $DpsName `
        --resource-group $Rg `
        --certificate-name $Name `
        --path $verification `
        --etag $etag `
        --only-show-errors `
        -o none
    Assert-Az "Verifica (proof of possession) della CA '$Name'"
    Write-Host "  CA '$Name' verificata su DPS." -ForegroundColor Green
}

function Test-HubAcceptsCertificate {
    <#
    .SYNOPSIS
    Sends one test message to the IoT Hub with the device's certificate and returns the HTTP status code.
    .DESCRIPTION
    204 (or 200) means the Hub accepted the certificate; 401 means it refused it (for example after a revocation).
    The leaf certificate and the private key are read from the device folder (issued-chain.pem, device-key.pem), as written by Register-DemoDevice.
    .PARAMETER Hub
    Host name of the Hub, for example iot-iot26-dev-uks-002.azure-devices.net.
    .PARAMETER DeviceId
    Registration ID of the device.
    .PARAMETER StateDir
    Folder of the device with issued-chain.pem and device-key.pem.
    .OUTPUTS
    The HTTP status code (int).
    #>
    param(
        [Parameter(Mandatory)][string]$Hub,
        [Parameter(Mandatory)][string]$DeviceId,
        [Parameter(Mandatory)][string]$StateDir
    )

    # issued-chain.pem holds leaf + CAs; TLS client authentication needs the leaf (the first block) with its key.
    $chain = [IO.File]::ReadAllText((Join-Path $StateDir 'issued-chain.pem'))
    $leaf  = [regex]::Match($chain, '-----BEGIN CERTIFICATE-----.*?-----END CERTIFICATE-----', 'Singleline').Value
    $key   = [IO.File]::ReadAllText((Join-Path $StateDir 'device-key.pem'))
    $c     = [Security.Cryptography.X509Certificates.X509Certificate2]::CreateFromPem($leaf, $key)

    # Exported and imported as PFX: Windows cannot use an ephemeral key for TLS client authentication.
    $pfxBytes = $c.Export([Security.Cryptography.X509Certificates.X509ContentType]::Pfx)
    $pfx      = [Security.Cryptography.X509Certificates.X509Certificate2]::new($pfxBytes)

    try {
        $body = @{ test = 'connection check'; ts = (Get-Date).ToUniversalTime().ToString('o') } | ConvertTo-Json -Compress

        # The device-to-cloud REST endpoint. The device is identified by the certificate (no SAS token).
        # -SkipHttpErrorCheck: a 401 must come back as a status code, not as an exception.
        $r = Invoke-WebRequest -Method Post `
            -Uri "https://$Hub/devices/$DeviceId/messages/events?api-version=2021-04-12" `
            -Certificate $pfx `
            -ContentType 'application/json' `
            -Body $body `
            -SkipHttpErrorCheck `
            -TimeoutSec 30
        [int]$r.StatusCode
    }
    finally {
        $pfx.Dispose()
        $c.Dispose()
    }
}

function Test-MqttBrokerAcceptsCertificate {
    <#
    .SYNOPSIS
    Connects to an MQTT broker over TLS with a client certificate and says whether the broker accepted it.
    .DESCRIPTION
    It does what an MQTT client does in its first moment: opens a TLS connection presenting the certificate, sends a CONNECT
    packet and reads the answer (CONNACK). Nothing is published or subscribed.
    Three outcomes tell different stories:
      accepted                       the certificate was trusted and the client is known to the broker
      refused: ... CONNACK code N    the TLS handshake passed (the certificate chain is trusted) but the broker refused the client
      refused: <TLS error>           the broker did not even accept the TLS handshake
    Event Grid never ends in the third case for a certificate it does not trust: it lets the handshake pass and answers CONNACK 5 to
    the CONNECT, whatever the reason (unknown CA, client not registered, certificate it does not accept). Observed on 2026-11-22.
    By default it uses the certificate ADR issued to the device (issued-chain.pem and device-key.pem); a second certificate
    can be tried with -CertFile and -KeyFile (the notebooks use the bootstrap certificate as a control).
    .PARAMETER Hostname
    Host name of the broker, for example the MQTT host name of an Event Grid namespace.
    .PARAMETER DeviceId
    The name the client presents: client id and user name. For Event Grid it is the client authentication name.
    .PARAMETER StateDir
    Folder of the device (it holds the certificate and the key files).
    .PARAMETER CertFile
    Certificate file in StateDir (default issued-chain.pem: the first certificate of the file is the one used).
    .PARAMETER KeyFile
    Private key file in StateDir (default device-key.pem).
    .PARAMETER Port
    TCP port (default 8883, MQTT over TLS).
    .PARAMETER SkipServerCertificateCheck
    Do not check the certificate of the broker. Only for a test broker on this computer: never for a real service.
    .OUTPUTS
    One line of text: 'accepted' or 'refused: <reason>'.
    #>
    param(
        [Parameter(Mandatory)][string]$Hostname,
        [Parameter(Mandatory)][string]$DeviceId,
        [Parameter(Mandatory)][string]$StateDir,
        [string]$CertFile = 'issued-chain.pem',
        [string]$KeyFile = 'device-key.pem',
        [int]$Port = 8883,
        [switch]$SkipServerCertificateCheck
    )

    # The client certificate with its private key. Exported and imported as PFX: Windows cannot use an ephemeral key for TLS.
    $pem  = [IO.File]::ReadAllText((Join-Path $StateDir $CertFile))
    $leaf = [regex]::Match($pem, '-----BEGIN CERTIFICATE-----.*?-----END CERTIFICATE-----', 'Singleline').Value
    $key  = [IO.File]::ReadAllText((Join-Path $StateDir $KeyFile))
    $c    = [Security.Cryptography.X509Certificates.X509Certificate2]::CreateFromPem($leaf, $key)
    $cert = [Security.Cryptography.X509Certificates.X509Certificate2]::new($c.Export([Security.Cryptography.X509Certificates.X509ContentType]::Pfx))
    $c.Dispose()

    $tcp = $null
    $ssl = $null
    try {
        $tcp = [Net.Sockets.TcpClient]::new()
        $tcp.ReceiveTimeout = 15000
        $tcp.SendTimeout    = 15000
        $tcp.Connect($Hostname, $Port)

        # The TLS handshake: here the broker decides whether it trusts the certificate chain.
        $ssl = [Net.Security.SslStream]::new($tcp.GetStream(), $false)
        $options = [Net.Security.SslClientAuthenticationOptions]::new()
        $options.TargetHost = $Hostname
        if ($SkipServerCertificateCheck) { $options.RemoteCertificateValidationCallback = { $true } }
        $options.ClientCertificates = [Security.Cryptography.X509Certificates.X509CertificateCollection]::new()
        [void]$options.ClientCertificates.Add($cert)
        $ssl.AuthenticateAsClient($options)

        # CONNECT, then CONNACK: 4 bytes (type 0x20, length 2, session flags, return code).
        $packet = New-MqttConnectPacket -ClientId $DeviceId -Username $DeviceId
        $ssl.Write($packet, 0, $packet.Length)
        $ssl.Flush()

        $reply = [byte[]]::new(4)
        $read  = 0
        while ($read -lt 4) {
            $n = $ssl.Read($reply, $read, 4 - $read)
            if ($n -le 0) { break }
            $read += $n
        }

        if ($read -lt 4)       { return 'refused: the broker closed the connection after the TLS handshake' }
        if ($reply[0] -ne 0x20) { return "refused: unexpected answer (first byte $($reply[0]))" }
        if ($reply[3] -eq 0)   { return 'accepted' }
        return "refused: CONNACK code $($reply[3])"
    }
    catch {
        return "refused: $($_.Exception.Message)"
    }
    finally {
        if ($ssl) { $ssl.Dispose() }
        if ($tcp) { $tcp.Dispose() }
        $cert.Dispose()
    }
}

function Wait-AdrNamespace {
    <#
    .SYNOPSIS
    Waits until the ADR namespace reports provisioningState = Succeeded.
    .DESCRIPTION
    A namespace is created asynchronously. Polls every 10 seconds, at most 30 times; throws on 'Failed' or on timeout.
    .PARAMETER Url
    ARM URL of the namespace, with the api-version.
    #>
    param(
        [Parameter(Mandatory)][string]$Url
    )

    # Up to 30 x 10 s = 5 minutes. The ADR namespace is a preview resource without an 'az ... wait' command,
    # so the state is read directly from ARM with 'az rest'.
    for ($i = 1; $i -le 30; $i++) {
        # 2>$null: a transient error while the resource is being created is not fatal; try again.
        $state = az rest --method get --url $Url --query properties.provisioningState -o tsv --only-show-errors 2>$null

        if ($state -eq 'Succeeded') { return }
        if ($state -eq 'Failed')    { throw 'Provisioning del namespace fallito.' }

        Write-Host "  provisioning namespace: $state ($i/30)" -ForegroundColor DarkGray
        Start-Sleep -Seconds 10
    }

    throw 'Timeout nel provisioning del namespace.'
}

# ===== Payload =============================================================================================

function Get-DevicePayloadTelemetry {
    <#
    .SYNOPSIS
    Runs a payload in a separate scope and returns what its Get-Telemetry function returns.
    .PARAMETER ScriptPath
    The payload file; it must define a function named Get-Telemetry.
    #>
    param(
        [Parameter(Mandatory)][string]$ScriptPath
    )

    # WHY the child scope "& { ... }": dot-sourcing defines Get-Telemetry inside that scope only, so the payload's
    # functions and variables vanish afterwards and one payload version cannot leak into the next.
    # WHY text + Create(): the kernel cannot run .ps1 files (execution policy), but it can run a scriptblock built from text.
    & {
        . ([scriptblock]::Create([IO.File]::ReadAllText($ScriptPath)))
        Get-Telemetry
    }
}

function Install-Payload {
    <#
    .SYNOPSIS
    DEVICE side: staging, signature check, trial run, promotion; otherwise rollback to the last known good version.
    .DESCRIPTION
    Takes thermostat-<Version>.ps1 and its manifest from <Root>\server\outbox. If the signature is wrong the current payload
    does not change. Otherwise the current payload is kept as last-known-good, the new one becomes current and is run once:
    if the trial fails (no exception allowed, a temperature required) the previous version is restored.
    The device folder is <Root>\device (payload\current.ps1, payload\last-known-good.ps1, signing-public.pem).
    .PARAMETER Version
    Version to install.
    .PARAMETER Root
    Base folder of the demo (it contains server\ and device\).
    .OUTPUTS
    One line of text that says what happened.
    .NOTES
    Replaces the function that used to be defined inside notebook 06, which read $root from the notebook.
    #>
    param(
        [Parameter(Mandatory)][string]$Version,
        [Parameter(Mandatory)][string]$Root
    )

    $pay   = Join-Path $Root 'device\payload'
    $inbox = Join-Path $Root 'server\outbox'
    $new   = Join-Path $inbox "thermostat-$Version.ps1"
    $man   = Join-Path $inbox "thermostat-$Version.json"

    # 1) Verify BEFORE touching anything: the device trusts only what the server signed.
    #    On a bad signature the current payload stays exactly as it was.
    $r = Test-PayloadSignature -ScriptPath $new -ManifestPath $man -PublicKeyPath (Join-Path $Root 'device\signing-public.pem')
    if ($r -ne 'ok') {
        "[$Version] RIFIUTATO: $r. Il payload corrente non cambia."
        return
    }

    # 2) Promote: keep the running version as "last known good" (the way back), then make the new one current.
    $cur = Join-Path $pay 'current.ps1'
    $lkg = Join-Path $pay 'last-known-good.ps1'
    if (Test-Path $cur) { Copy-Item $cur $lkg -Force }
    Copy-Item $new $cur -Force

    # 3) Trial run: a valid signature proves who wrote the code, not that it works.
    #    Run it once; no exception and a temperature in the result are required.
    #    If it fails, restore the last known good version, so the device never ends with a broken payload.
    try {
        $t = Get-DevicePayloadTelemetry $cur
        if ($null -eq $t.temperature) { throw 'telemetria senza temperatura' }
        "[$Version] firma ok, prova superata: ATTIVO."
    }
    catch {
        Copy-Item $lkg $cur -Force
        "[$Version] firma ok ma la PROVA e' fallita ($($_.Exception.Message)): ritorno alla versione precedente."
    }
}

function Publish-Payload {
    <#
    .SYNOPSIS
    SERVER side: signs a payload and writes the script and its manifest to the outbox.
    .DESCRIPTION
    Writes thermostat-<Version>.ps1 and thermostat-<Version>.json. The manifest holds the version, the SHA-256 of the file
    and the ECDSA P-384 / SHA-384 signature (IEEE P1363, hex).
    .PARAMETER Version
    Version of the payload, for example 1.0.0.
    .PARAMETER Script
    The text of the payload.
    .PARAMETER Dir
    Outbox folder.
    .PARAMETER SigningKey
    Private signing key (System.Security.Cryptography.ECDsa). Only the server has it.
    .NOTES
    Replaces the function that used to be defined inside notebook 06, which read the key from $signKey.
    #>
    param(
        [Parameter(Mandatory)][string]$Version,
        [Parameter(Mandatory)][string]$Script,
        [Parameter(Mandatory)][string]$Dir,
        [Parameter(Mandatory)][Security.Cryptography.ECDsa]$SigningKey
    )

    # Sign the exact bytes that will be written to disk (UTF-8, no BOM): the device hashes and verifies the file bytes,
    # so signing a differently encoded copy would never match.
    $bytes = [Text.UTF8Encoding]::new($false).GetBytes($Script)

    # IEEE P1363 = raw r||s, fixed length: the same format on every platform (the default would be DER).
    $sig = $SigningKey.SignData(
        $bytes,
        [Security.Cryptography.HashAlgorithmName]::SHA384,
        [Security.Cryptography.DSASignatureFormat]::IeeeP1363FixedFieldConcatenation)

    [IO.File]::WriteAllBytes((Join-Path $Dir "thermostat-$Version.ps1"), $bytes)

    # The manifest travels with the script: version, signature, and a SHA-256 that gives a first,
    # clearer "file was altered" answer before the signature is checked.
    [ordered]@{
        version = $Version
        sig     = [Convert]::ToHexString($sig).ToLower()
        sha256  = [Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($bytes)).ToLower()
    } | ConvertTo-Json | Set-Content (Join-Path $Dir "thermostat-$Version.json") -Encoding utf8
}

function Test-PayloadSignature {
    <#
    .SYNOPSIS
    DEVICE side: checks the hash and the signature of a payload with the public key.
    .PARAMETER ScriptPath
    The payload file.
    .PARAMETER ManifestPath
    Its manifest (JSON).
    .PARAMETER PublicKeyPath
    PEM file with the public signing key (the only key the device holds).
    .OUTPUTS
    'ok', 'hash diverso' (the file was altered) or 'firma non valida' (the signature does not match).
    #>
    param(
        [Parameter(Mandatory)][string]$ScriptPath,
        [Parameter(Mandatory)][string]$ManifestPath,
        [Parameter(Mandatory)][string]$PublicKeyPath
    )

    # The device holds only the PUBLIC key: it can verify signatures but never create one.
    $pub = [Security.Cryptography.ECDsa]::Create()
    $pub.ImportFromPem([IO.File]::ReadAllText($PublicKeyPath))

    $bytes = [IO.File]::ReadAllBytes($ScriptPath)
    $m     = Get-Content $ManifestPath -Raw | ConvertFrom-Json

    # First check: the hash. It tells apart "the file changed" from "the signature is wrong".
    $hash = [Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($bytes)).ToLower()
    if ($hash -ne $m.sha256) {
        return 'hash diverso'
    }

    # Second check: the signature, over the same bytes and with the same format used by Publish-Payload.
    $ok = $pub.VerifyData(
        $bytes,
        [Convert]::FromHexString($m.sig),
        [Security.Cryptography.HashAlgorithmName]::SHA384,
        [Security.Cryptography.DSASignatureFormat]::IeeeP1363FixedFieldConcatenation)

    if ($ok) { 'ok' } else { 'firma non valida' }
}

# ===== Device ==============================================================================================

function Add-DeviceEvent {
    # WHAT: records something that happened to a device, in memory ($Dev.Events) and in its device.log file.
    # WHY:  the notebooks show the story of each device (registered, renewed, refused...) as a table, and the log
    #       stays on the device's "disk" like a real device log would.
    # HOW:  the time stamp is the SIMULATED time (Get-SimNow), so the log reads like the days of the demo, not like the minutes it took to run.
    param(
        $Dev,
        [string]$What
    )

    # Same news as the last event: say it once. Without this an offline device would add one identical line every simulated day.
    if ($Dev.Events.Count -gt 0 -and $Dev.Events[$Dev.Events.Count - 1].Event -eq $What) {
        return
    }

    $Dev.Events.Add([pscustomobject]@{
        Day    = [math]::Round($global:Sim.Day, 1)
        Device = $Dev.Id
        Event  = $What
    })

    $line = "{0:yyyy-MM-dd HH:mm} (day {1:n1}) {2}" -f (Get-SimNow), $global:Sim.Day, $What
    Add-Content -Path (Join-Path $Dev.Dir 'device.log') -Value $line -Encoding utf8
}

function Get-DeviceCertStatus {
    # WHAT: the state of the device's operational certificate: none, valid, renew-due or expired, with days left and thumbprint.
    # WHY:  it is what the application sees every day: how much life is left in the operational certificate.
    #       Invoke-DeviceTick decides from this state whether to register, renew or do nothing.
    # HOW:  reads issued-chain.pem from the device folder and compares its dates with the SIMULATED now.
    param(
        $Dev
    )

    $path = Join-Path $Dev.Dir 'issued-chain.pem'

    # No file = the device never registered: report it as a state, not as an error.
    if (-not (Test-Path $path)) {
        return [pscustomobject]@{
            Device     = $Dev.Id
            State      = 'none'
            DaysLeft   = $null
            LifeDays   = $null
            NotAfter   = $null
            Thumbprint = $null
        }
    }

    # The chain file holds several certificates; the first block is the device's own (the leaf).
    $m = [regex]::Match([IO.File]::ReadAllText($path), '-----BEGIN CERTIFICATE-----.*?-----END CERTIFICATE-----', 'Singleline')
    $c = [Security.Cryptography.X509Certificates.X509Certificate2]::CreateFromPem($m.Value)

    try {
        $now = Get-SimNow

        # Days left from the simulated now, and the total life of this certificate (NotAfter - NotBefore).
        $left = ([DateTimeOffset]$c.NotAfter - $now).TotalDays
        $life = ([DateTimeOffset]$c.NotAfter - [DateTimeOffset]$c.NotBefore).TotalDays

        # Renewal rule: when 20% or less of the life is left, ask for a new certificate (so a failure has time to be retried).
        $state = if ($left -le 0) { 'expired' }
                 elseif ($left / $life -le 0.2) { 'renew-due' }
                 else { 'valid' }

        [pscustomobject]@{
            Device     = $Dev.Id
            State      = $state
            DaysLeft   = [math]::Round($left, 1)
            LifeDays   = [math]::Round($life, 1)
            NotAfter   = ([DateTimeOffset]$c.NotAfter).ToString('yyyy-MM-dd')
            # 12 characters are enough to tell two certificates apart in a table.
            Thumbprint = $c.Thumbprint.Substring(0, 12)
        }
    }
    finally {
        $c.Dispose()
    }
}

function Get-FleetCertTable {
    # WHAT: one row per device with certificate state, days left, expiry, thumbprint and bootstrap expiry.
    # WHY:  the fleet at a glance in a notebook cell: who is valid, who must renew, whose bootstrap credential is about to expire.
    # HOW:  asks Get-DeviceCertStatus for each device and adds the fields that belong to the device itself (Online, bootstrap date).
    param(
        [Parameter(Mandatory)]$Devices
    )

    $Devices | ForEach-Object {
        $s = Get-DeviceCertStatus $_
        [pscustomobject]@{
            Device           = $_.Id
            Online           = $_.Online
            Certificate      = $s.State
            DaysLeft         = $s.DaysLeft
            Expires          = $s.NotAfter
            Thumbprint       = $s.Thumbprint
            BootstrapExpires = $_.BootstrapNotAfter.ToString('yyyy-MM-dd')
        }
    }
}

function Get-SimNow {
    # WHAT: the current time of the simulation.
    # WHY:  certificates last weeks; the demo lasts minutes. Everything that asks "what time is it?" asks here, so time can be moved forward.
    # HOW:  the real time at Initialize-Sim plus the simulated days elapsed (Step-Sim moves $global:Sim.Day).
    $global:Sim.Base.AddDays($global:Sim.Day)
}

function Initialize-Sim {
    # WHAT: starts the simulated clock.
    # WHY:  time starts now; Step-Sim moves it forward. Certificates are issued with simulated dates.
    # HOW:  the state lives in the global $Sim because the notebook cells share one session and every function reads it.
    #       Base = real "now" (UTC), Day = simulated days elapsed since then.
    $global:Sim = @{
        Base = [DateTimeOffset]::UtcNow
        Day  = 0.0
    }
}

function Invoke-DeviceRegistration {
    # WHAT: the step that issues a certificate: NEW key, NEW CSR, authenticate with the bootstrap credential, receive the chain.
    # WHY:  first registration and renewal are the same call: the device just asks again. A renewal is a new key, not an extension.
    # HOW:  calls the real DPS through the az CLI (the device needs $Dev.Dps). Returns $true when a new certificate is now on the
    #       device, $false when it could not get one (the reason goes in the device log).
    param(
        $Dev,
        [string]$Reason
    )

    # Registration always goes to the real service: without a DPS there is nothing to register to.
    if (-not $Dev.Dps) {
        throw "Device $($Dev.Id) has no DPS: give New-SimDevice a -Dps @{ Name; Rg }."
    }

    # An offline device cannot reach DPS: log it and let the next daily tick retry.
    if (-not $Dev.Online) {
        Add-DeviceEvent $Dev 'cannot reach DPS (offline): will retry every day'
        return $false
    }

    # The bootstrap credential has its own life. Once expired DPS refuses it, and only a new bootstrap certificate fixes that.
    if ((Get-SimNow) -gt $Dev.BootstrapNotAfter) {
        Add-DeviceEvent $Dev "bootstrap credential EXPIRED on $($Dev.BootstrapNotAfter.ToString('yyyy-MM-dd')): DPS would refuse the registration (needs a new bootstrap certificate)"
        return $false
    }

    # New key and CSR go in a 'pending' folder: the files in use stay untouched until the new ones are really issued.
    $work = Join-Path $Dev.Dir 'pending'
    # The private key never leaves the device.
    $csr = New-DemoCsr -Cn $Dev.Id -Dir $work

    # The bootstrap chain + key authenticate, the CSR asks for the operational certificate.
    $json = az iot device registration create `
        --dps-name $Dev.Dps.Name `
        --resource-group $Dev.Dps.Rg `
        --registration-id $Dev.Id `
        --certificate-file-path (Join-Path $Dev.Dir 'bootstrap-chain.pem') `
        --key-file-path (Join-Path $Dev.Dir 'bootstrap-key.pem') `
        --auth-type login `
        --csr $csr.Csr `
        --timeout 120 `
        -o json `
        --only-show-errors
    if ($LASTEXITCODE -ne 0) {
        Add-DeviceEvent $Dev 'DPS registration failed'
        return $false
    }

    # Write issued-NN.pem and issued-chain.pem into the pending folder.
    [void](Export-IssuedChain -Json ($json -join "`n") -OutDir $work)

    # Remember which Hub DPS assigned (the JSON shape can be wrapped or flat).
    $reg = ($json -join "`n") | ConvertFrom-Json
    $Dev.AssignedHub = if ($null -ne $reg.registrationState) { $reg.registrationState.assignedHub } else { $reg.assignedHub }

    # Remembered on disk: a relaunch (-Reuse) with a valid certificate does not register again, and must still know its Hub.
    if ($Dev.AssignedHub) {
        [IO.File]::WriteAllText((Join-Path $Dev.Dir 'assigned-hub.txt'), $Dev.AssignedHub, [Text.UTF8Encoding]::new($false))
    }

    $pem = [IO.File]::ReadAllText((Join-Path $work 'issued-chain.pem'))

    # Keep the old material (history\), then switch to the new one.
    # The name carries the day counter of the clock, so the history shows how certificates followed one another.
    $hist = Join-Path $Dev.Dir 'history'
    New-Item -ItemType Directory -Force $hist | Out-Null
    foreach ($f in 'issued-chain.pem', 'device-key.pem') {
        $old = Join-Path $Dev.Dir $f
        if (Test-Path $old) {
            Move-Item $old (Join-Path $hist ("{0}-{1:000.0}-{2}" -f $Dev.Id, $global:Sim.Day, $f)) -Force
        }
    }

    # Switch: new chain and new key take the place of the old ones; the pending folder is no longer needed.
    [IO.File]::WriteAllText((Join-Path $Dev.Dir 'issued-chain.pem'), $pem, [Text.UTF8Encoding]::new($false))
    Move-Item $csr.Key (Join-Path $Dev.Dir 'device-key.pem') -Force
    Remove-Item $work -Recurse -Force -ErrorAction SilentlyContinue

    $s = Get-DeviceCertStatus $Dev
    Add-DeviceEvent $Dev "new certificate ($Reason): thumbprint $($s.Thumbprint)..., valid until $($s.NotAfter)"
    return $true
}

function Invoke-DeviceTick {
    # WHAT: the application's daily check on its own certificate.
    # WHY:  the decision is the device's, not the service's:
    #         no certificate -> register; expired -> register again with the bootstrap credential; 20% of life left -> renew.
    # HOW:  reads the state with Get-DeviceCertStatus and calls Invoke-DeviceRegistration when something is due.
    param(
        $Dev,
        [double]$RenewAtFraction = 0.2
    )

    $s = Get-DeviceCertStatus $Dev

    # Relaunched with a certificate but without the Hub on disk: the Hub is only learned from a registration, so register again.
    if ($Dev.Dps -and -not $Dev.AssignedHub -and $s.State -ne 'none') {
        [void](Invoke-DeviceRegistration $Dev 're-registration: assigned Hub unknown after relaunch')
        return
    }

    # 'valid' has no branch on purpose: nothing to do today.
    switch ($s.State) {
        'none'      { [void](Invoke-DeviceRegistration $Dev 'first registration') }
        'expired'   { [void](Invoke-DeviceRegistration $Dev 're-registration after expiry') }
        'renew-due' { [void](Invoke-DeviceRegistration $Dev ("renewal, {0:n1} of {1:n0} days left" -f $s.DaysLeft, $s.LifeDays)) }
    }
}

function New-DeviceClientCertificate {
    # WHAT: the device's leaf certificate and its private key, joined in one object that can be used for TLS client authentication.
    # WHY:  an HTTPS client (Invoke-RestMethod -Certificate) needs a certificate that carries its key; on disk they are two PEM files.
    # HOW:  PEM -> certificate with key -> exported as PFX -> imported again. The round trip is needed because Windows
    #       cannot use an ephemeral (in-memory only) key for client authentication: the PFX import gives it a persistable key.
    param(
        $Dev,
        # The notebooks also try the bootstrap certificate (bootstrap-cert.pem, bootstrap-key.pem) as a control.
        [string]$CertFile = 'issued-chain.pem',
        [string]$KeyFile = 'device-key.pem'
    )

    $chainPem = [IO.File]::ReadAllText((Join-Path $Dev.Dir $CertFile))

    # Only the first block (the leaf): the rest of the chain is not the client's certificate.
    $leafPem = [regex]::Match($chainPem, '-----BEGIN CERTIFICATE-----.*?-----END CERTIFICATE-----', 'Singleline').Value
    $keyPem  = [IO.File]::ReadAllText((Join-Path $Dev.Dir $KeyFile))
    $c = [Security.Cryptography.X509Certificates.X509Certificate2]::CreateFromPem($leafPem, $keyPem)

    try {
        # The caller owns the returned certificate and must Dispose it (Send-DeviceTelemetry does).
        [Security.Cryptography.X509Certificates.X509Certificate2]::new(
            $c.Export([Security.Cryptography.X509Certificates.X509ContentType]::Pfx))
    }
    finally {
        $c.Dispose()
    }
}

function New-DeviceTelemetry {
    # WHAT: builds one telemetry message: time stamp, device id, temperature, setpoint, payload version, alarm state.
    # WHY:  every device sends the same shape. deviceId is in the BODY on purpose: downstream readers must not depend on system properties.
    # HOW:  the temperature is the setpoint plus a random noise of +/- 0.6 degrees; above setpoint + 5 the alarm is 'high'.
    #       A caller can pass its own Random (with a seed) to get repeatable values.
    param(
        $Dev,
        [double]$Setpoint = 21,
        [Random]$Rng = [Random]::new()
    )

    # NextDouble() is in [0,1): minus 0.5 centres it on zero, times 1.2 makes the span 1.2 degrees.
    $t = [math]::Round($Setpoint + ($Rng.NextDouble() - 0.5) * 1.2, 2)

    [ordered]@{
        # ISO 8601 round-trip format ('o'), in UTC, from the simulated clock.
        ts             = (Get-SimNow).UtcDateTime.ToString('o')
        deviceId       = $Dev.Id
        temperature    = $t
        setpoint       = $Setpoint
        payloadVersion = '1.0.0'
        alarmState     = $(if ($t -gt $Setpoint + 5) { 'high' } else { 'ok' })
    }
}

function New-SimBootstrap {
    # WHAT: the onboarding credential of a device: a certificate signed by the fleet's bootstrap CA, with its key and chain file.
    # WHY:  it is only used to introduce the device to DPS, and it has its own life (here 30 days, like in notebook 02).
    # HOW:  like New-DemoLeaf, but the dates come from the simulated clock, unless -RealTime is used.
    #       Returns the expiry date of the credential (the device checks it before every registration).
    param(
        [Parameter(Mandatory)][string]$CaDir,
        [Parameter(Mandatory)][string]$Cn,
        [Parameter(Mandatory)][string]$Dir,
        [int]$Days = 30,
        # A real DPS checks the dates against the real clock: a certificate dated with the simulated clock (days ahead) is refused with 401002.
        [switch]$RealTime
    )

    $issuer = [Security.Cryptography.X509Certificates.X509Certificate2]::CreateFromPem(
        [IO.File]::ReadAllText((Join-Path $CaDir 'ca.pem')),
        [IO.File]::ReadAllText((Join-Path $CaDir 'ca-key.pem')))

    $curve = [Security.Cryptography.ECCurve]::CreateFromFriendlyName('nistP384')
    $ecdsa = [Security.Cryptography.ECDsa]::Create($curve)

    try {
        $req = [Security.Cryptography.X509Certificates.CertificateRequest]::new(
            "CN=$Cn",
            $ecdsa,
            [Security.Cryptography.HashAlgorithmName]::SHA384)
        $usage = [Security.Cryptography.X509Certificates.X509KeyUsageFlags]

        # A leaf for client authentication: not a CA, digital signature, clientAuth.
        $req.CertificateExtensions.Add(
            [Security.Cryptography.X509Certificates.X509BasicConstraintsExtension]::new($false, $false, 0, $true))
        $req.CertificateExtensions.Add(
            [Security.Cryptography.X509Certificates.X509KeyUsageExtension]::new($usage::DigitalSignature, $true))
        $eku = [Security.Cryptography.OidCollection]::new()
        [void]$eku.Add([Security.Cryptography.Oid]::new('1.3.6.1.5.5.7.3.2'))
        $req.CertificateExtensions.Add(
            [Security.Cryptography.X509Certificates.X509EnhancedKeyUsageExtension]::new($eku, $false))

        # Random positive 128-bit serial number (top bit cleared).
        $serial = [byte[]]::new(16)
        [Security.Cryptography.RandomNumberGenerator]::Fill($serial)
        $serial[0] = $serial[0] -band 0x7F

        # Real clock for a real DPS, simulated clock for the local simulation.
        $now  = if ($RealTime) { [DateTimeOffset]::UtcNow } else { Get-SimNow }
        $leaf = $req.Create($issuer, $now.AddMinutes(-5), $now.AddDays($Days), $serial)

        Write-Pem -Path (Join-Path $Dir 'bootstrap-key.pem')  -Label 'PRIVATE KEY' -Bytes $ecdsa.ExportPkcs8PrivateKey()
        Write-Pem -Path (Join-Path $Dir 'bootstrap-cert.pem') -Label 'CERTIFICATE' -Bytes $leaf.RawData

        # Chain file = leaf + CA, the file the az CLI sends to DPS.
        $chainText = [IO.File]::ReadAllText((Join-Path $Dir 'bootstrap-cert.pem')) +
                     [IO.File]::ReadAllText((Join-Path $CaDir 'ca.pem'))
        [IO.File]::WriteAllText((Join-Path $Dir 'bootstrap-chain.pem'), $chainText, [Text.UTF8Encoding]::new($false))

        $notAfter = [DateTimeOffset]$leaf.NotAfter
        $leaf.Dispose()
        return $notAfter
    }
    finally {
        $ecdsa.Dispose()
        $issuer.Dispose()
    }
}

function New-SimDevice {
    # WHAT: creates the object that represents a device: a folder (its "disk") plus a few settings.
    # WHY:  nothing here is shared with the cloud except the CSR; everything else is local state, so a device can be thrown away
    #       (delete the folder) or relaunched (-Reuse) like a real one.
    # HOW:  a hashtable with the settings; the bootstrap credential is either created (new device) or read back from disk (-Reuse).
    param(
        [Parameter(Mandatory)][string]$Id,
        [Parameter(Mandatory)][string]$Dir,
        [Parameter(Mandatory)][string]$BootstrapCaDir,
        # @{ Name; Rg } of the real DPS the device registers to.
        [Parameter(Mandatory)][hashtable]$Dps,
        [int]$ValidityDays = 30,
        [int]$BootstrapDays = 365,
        [switch]$Reuse
    )

    New-Item -ItemType Directory -Force $Dir | Out-Null

    $dev = @{
        Id                = $Id
        Dir               = $Dir
        BootstrapCaDir    = $BootstrapCaDir
        ValidityDays      = $ValidityDays
        Dps               = $Dps
        AssignedHub       = $null
        Online            = $true
        BootstrapNotAfter = $null
        Events            = [System.Collections.Generic.List[object]]::new()
    }

    if ($Reuse -and (Test-Path (Join-Path $Dir 'bootstrap-cert.pem'))) {
        # Relaunch: keep the bootstrap credential and the operational certificate already on the "disk".
        # The expiry date is read from the certificate itself, so it is not stored twice.
        $b = [Security.Cryptography.X509Certificates.X509Certificate2]::CreateFromPem(
            [IO.File]::ReadAllText((Join-Path $Dir 'bootstrap-cert.pem')))
        $dev.BootstrapNotAfter = [DateTimeOffset]$b.NotAfter
        $b.Dispose()

        # The Hub was written by Invoke-DeviceRegistration: without it the device would have to register again.
        $hubFile = Join-Path $Dir 'assigned-hub.txt'
        if (Test-Path $hubFile) {
            $dev.AssignedHub = ([IO.File]::ReadAllText($hubFile)).Trim()
        }
    }
    else {
        # New device: issue its bootstrap credential. DPS checks the dates against the real clock, hence -RealTime.
        $dev.BootstrapNotAfter = New-SimBootstrap `
            -CaDir $BootstrapCaDir `
            -Cn $Id `
            -Dir $Dir `
            -Days $BootstrapDays `
            -RealTime
    }

    return $dev
}

function Send-DeviceTelemetry {
    # WHAT: sends one telemetry message of a device.
    # WHY:  with an assigned Hub the message really goes to the IoT Hub; otherwise (local simulation or -DryRun) it is only
    #       written to the device folder, so the demo works without Azure. The real send is NOT proven (see README).
    # HOW:  real: POST https://<hub>/devices/<id>/messages/events with the TLS client certificate.
    #       local: one JSON line appended to telemetry-out.jsonl.
    #       Returns 'sent' or 'dry-run'.
    param(
        $Dev,
        [Parameter(Mandatory)]$Message,
        [switch]$DryRun
    )

    $json = $Message | ConvertTo-Json -Compress

    # No Hub assigned means the device never registered with a real DPS: nowhere to send to.
    if ($DryRun -or -not $Dev.AssignedHub) {
        Add-Content -Path (Join-Path $Dev.Dir 'telemetry-out.jsonl') -Value $json -Encoding utf8
        return 'dry-run'
    }

    # The device authenticates with its operational certificate (no SAS token, no shared key).
    $cert = New-DeviceClientCertificate $Dev
    try {
        Invoke-RestMethod -Method Post `
            -Uri "https://$($Dev.AssignedHub)/devices/$($Dev.Id)/messages/events?api-version=2021-04-12" `
            -Certificate $cert `
            -ContentType 'application/json' `
            -Body $json | Out-Null
        return 'sent'
    }
    finally {
        $cert.Dispose()
    }
}

# ===== Launcher ============================================================================================

function Format-Arg {
    <#
    .SYNOPSIS
    Quotes a command-line argument when it contains white space.
    .PARAMETER a
    The argument.
    .EXAMPLE
    @('-File', 'C:\My Folder\_run-device.ps1') | ForEach-Object { Format-Arg $_ }   # -File and "C:\My Folder\_run-device.ps1"
    #>
    param(
        $a
    )

    # WHY: Start-Process joins -ArgumentList into ONE string; an argument with a space (a path such as "C:\My Folder\...")
    # would be split in two by the new process. Quoting the ones that need it keeps them whole; the others stay as they are.
    if ("$a" -match '\s') {
        "`"$a`""
    }
    else {
        "$a"
    }
}

function Start-DemoCertApi {
    <#
    .SYNOPSIS
    Starts the certificate API (api\cert-api.cs) in the background and waits until it answers.
    .DESCRIPTION
    The API only lets in clients whose certificate was issued by ADR (see the header of cert-api.cs). It runs on this
    computer with `dotnet run`: the first start compiles it and takes a few seconds.
    The output goes to a log file in the temp folder, not to the repository.
    Stop it with: & taskkill /PID $process.Id /T /F  (`dotnet run` starts a child process: /T stops both).
    .PARAMETER ApiFile
    Full path of cert-api.cs.
    .PARAMETER TrustFile
    PEM with the ADR Root CA and Issuing CA (adr-trust.pem, from Export-AdrCaCertificates).
    .PARAMETER Port
    Local HTTPS port (default 8443).
    .PARAMETER TimeoutSeconds
    How long to wait for the first start (default 150).
    .OUTPUTS
    The process. The log is in $env:TEMP\cert-api.log (and .err).
    #>
    param(
        [Parameter(Mandatory)][string]$ApiFile,
        [Parameter(Mandatory)][string]$TrustFile,
        [int]$Port = 8443,
        [int]$TimeoutSeconds = 150
    )

    if (-not (Test-Path $ApiFile))   { throw "Missing $ApiFile." }
    if (-not (Test-Path $TrustFile)) { throw "Missing ${TrustFile}: run Export-AdrCaCertificates first." }

    # Output and errors go to files: a hidden process has no window to print in.
    $log = Join-Path ([IO.Path]::GetTempPath()) 'cert-api.log'
    $arguments = @('run', (Format-Arg $ApiFile), '--', (Format-Arg $TrustFile), $Port)
    $process = Start-Process dotnet -ArgumentList $arguments -PassThru -WindowStyle Hidden `
        -RedirectStandardOutput $log -RedirectStandardError "$log.err"

    # Wait until the port accepts connections; stop early if the process died (a compile error, for instance).
    $deadline = (Get-Date).AddSeconds($TimeoutSeconds)
    while ((Get-Date) -lt $deadline) {
        if ($process.HasExited) {
            throw "The API stopped at start: $((Get-Content "$log.err" -Raw)) $((Get-Content $log -Raw))"
        }
        try {
            $probe = [Net.Sockets.TcpClient]::new('localhost', $Port)
            $probe.Dispose()
            return $process
        }
        catch {
            Start-Sleep -Milliseconds 700
        }
    }

    & taskkill /PID $process.Id /T /F 2>&1 | Out-Null
    throw "The API did not answer on port $Port within $TimeoutSeconds seconds."
}

# ===== Operations ==========================================================================================

function Get-AdrDeviceState {
    <#
    .SYNOPSIS
    Enablement state (Enabled or Disabled) of a device in the ADR namespace.
    .PARAMETER Name
    Device name.
    .PARAMETER Namespace
    ADR namespace name.
    .PARAMETER ResourceGroup
    Resource group of the namespace.
    #>
    param(
        [Parameter(Mandatory)][string]$Name,
        [Parameter(Mandatory)][string]$Namespace,
        [Parameter(Mandatory)][string]$ResourceGroup
    )

    # --query + -o tsv returns just the value as plain text, with no JSON to parse.
    $s = az iot adr ns device show `
        --name $Name `
        --namespace $Namespace `
        --resource-group $ResourceGroup `
        --query 'properties.enablementState' `
        -o tsv `
        --only-show-errors
    Assert-Az "Lettura dello stato di $Name"

    # The value is the output of the function.
    $s
}

function Get-AdrGroupMembers {
    <#
    .SYNOPSIS
    Names of the devices that belong to an ADR group now.
    .DESCRIPTION
    Membership is a snapshot taken when the group is created or refreshed: it does not follow later changes of the devices.
    .PARAMETER Name
    Group name.
    .PARAMETER Namespace
    ADR namespace name.
    .PARAMETER ResourceGroup
    Resource group of the namespace.
    #>
    param(
        [Parameter(Mandatory)][string]$Name,
        [Parameter(Mandatory)][string]$Namespace,
        [Parameter(Mandatory)][string]$ResourceGroup
    )

    $json = az iot adr ns group list-members `
        --name $Name `
        --namespace $Namespace `
        --resource-group $ResourceGroup `
        -o json `
        --only-show-errors
    Assert-Az "Lettura dei membri di $Name"

    # Each member comes as an ARM resource id; the device name is its last segment.
    # @() keeps a one-member group a list.
    @($json | ConvertFrom-Json) | ForEach-Object { ($_.id -split '/')[-1] }
}

function Get-HubMessageCounts {
    <#
    .SYNOPSIS
    Messages accepted by an IoT Hub and messages delivered to its routes, over the last hours.
    .DESCRIPTION
    Reads two Azure Monitor metrics of the Hub: d2c.telemetry.ingress.success (messages that entered) and
    d2c.telemetry.egress.success (deliveries to routing endpoints: one message counts once per route that matches).
    The metrics arrive with a delay of a few minutes, so a zero right after sending is normal.
    .PARAMETER HubName
    IoT Hub name.
    .PARAMETER ResourceGroup
    Resource group of the Hub.
    .PARAMETER Hours
    Time window, ending now.
    .OUTPUTS
    An object with Hub, Ingress and Egress (numbers; 0 when the metric has no data).
    #>
    param(
        [Parameter(Mandatory)][string]$HubName,
        [Parameter(Mandatory)][string]$ResourceGroup,
        [int]$Hours = 1
    )

    # Azure Monitor addresses a resource by its full ARM id.
    $id = az iot hub show --name $HubName --resource-group $ResourceGroup --query id -o tsv --only-show-errors
    Assert-Az "Lettura dell'Hub $HubName"

    # The same query for two metrics: a scriptblock called twice, with the metric name as argument.
    $read = {
        param($metric)

        # 'sum( ... )' needs the spaces: PowerShell passes a bare 'sum(...)' to az.cmd unquoted.
        # The JMESPath expression adds up the hourly totals of the first (only) time series.
        $v = az monitor metrics list `
            --resource $id `
            --metric $metric `
            --aggregation Total `
            --interval PT1H `
            --offset "${Hours}h" `
            --query 'sum( value[0].timeseries[0].data[].total )' `
            -o tsv `
            --only-show-errors

        # No data (empty output) is reported as 0, not as an error.
        if ($v) { [double]$v } else { 0 }
    }

    [pscustomobject]@{
        Hub     = $HubName
        Ingress = (& $read 'd2c.telemetry.ingress.success')
        Egress  = (& $read 'd2c.telemetry.egress.success')
    }
}

function Grant-HubDataAccess {
    <#
    .SYNOPSIS
    Gives the signed-in user the data-plane role on an IoT Hub (once) and waits until the Hub answers.
    .DESCRIPTION
    Being Owner of the subscription is not enough to read the devices of an Hub with `--auth-type login`: the Hub needs the role
    "IoT Hub Data Contributor", assigned on that Hub. Without it the Hub answers IotHubUnauthorized ("no assigned permissions").
    The role is assigned only if it is missing, then the function asks the Hub for its devices until the answer is no longer
    an authorization error: a new role takes a few minutes to propagate.
    Call it once per Hub before any `az iot hub device-identity ... --auth-type login`.
    .PARAMETER HubName
    IoT Hub name.
    .PARAMETER ResourceGroup
    Resource group of the Hub.
    .PARAMETER TimeoutSeconds
    How long to wait for the role to propagate (default 300).
    #>
    param(
        [Parameter(Mandatory)][string]$HubName,
        [Parameter(Mandatory)][string]$ResourceGroup,
        [int]$TimeoutSeconds = 300
    )

    $role = 'IoT Hub Data Contributor'

    # Who am I (object id of the signed-in user) and what is the Hub's id (the scope of the role)?
    $me = az ad signed-in-user show --query id -o tsv --only-show-errors
    Assert-Az "Lettura dell'utente connesso"
    $hubId = az iot hub show --name $HubName --resource-group $ResourceGroup --query id -o tsv --only-show-errors
    Assert-Az "Lettura dell'Hub $HubName"

    # Is the role already assigned on this Hub? Empty answer = no. 2>$null: "not found" is not an error here.
    $has = az role assignment list `
        --assignee $me `
        --scope $hubId `
        --role $role `
        --query '[0].id' `
        -o tsv `
        --only-show-errors 2>$null

    if (-not $has) {
        # --assignee-object-id + principal type User: no lookup in Entra needed, so it is faster and avoids replication errors.
        az role assignment create `
            --assignee-object-id $me `
            --assignee-principal-type User `
            --role $role `
            --scope $hubId `
            -o none `
            --only-show-errors
        Assert-Az "Assegnazione del ruolo $role su $HubName"
        "${HubName}: ruolo $role assegnato."
    }

    # A new role takes minutes to propagate: ask the Hub something that needs the role until it answers.
    $deadline = (Get-Date).AddSeconds($TimeoutSeconds)
    while ($true) {
        az iot hub device-identity list `
            --hub-name $HubName `
            --resource-group $ResourceGroup `
            --auth-type login `
            --query '[0].deviceId' `
            -o none `
            --only-show-errors 2>$null

        if ($LASTEXITCODE -eq 0) {
            "${HubName}: accesso ai dati pronto."
            return
        }
        if ((Get-Date) -gt $deadline) {
            throw "L'Hub $HubName non risponde dopo $TimeoutSeconds secondi: il ruolo $role non si e' ancora propagato."
        }

        "${HubName}: attendo la propagazione del ruolo..."
        Start-Sleep -Seconds 15
    }
}

function Invoke-DeviceUpdateCheck {
    <#
    .SYNOPSIS
    Starts the update agent of a device as its own process: it asks for an update, installs it if there is one, reports, and ends.
    .DESCRIPTION
    The agent is device\su-agent\su-agent.cs (C#, run with `dotnet run`). It is a device: it opens an MQTT session to DPS with the
    bootstrap certificate of the device and PULLS - the service never pushes. Every step it takes prints one line, and this function
    returns those lines. The first start compiles the agent and takes a few seconds.
    .PARAMETER Device
    Registration id of the device.
    .PARAMETER Folder
    Folder of the device with bootstrap-chain.pem and bootstrap-key.pem (the one Register-DemoDevice wrote).
    .PARAMETER State
    Folder where the device keeps what it installed (installed.json, payload\current.ps1). Deleting it makes the device forget.
    .PARAMETER IdScope
    ID scope of the DPS.
    .PARAMETER AgentFile
    Path of su-agent.cs.
    .PARAMETER Manufacturer
    Manufacturer the device declares (compatibility property).
    .PARAMETER Model
    Model the device declares (compatibility property).
    .OUTPUTS
    The lines the agent printed, as strings.
    #>
    param(
        [Parameter(Mandatory)][string]$Device,
        [Parameter(Mandatory)][string]$Folder,
        [Parameter(Mandatory)][string]$State,
        [Parameter(Mandatory)][string]$IdScope,
        [Parameter(Mandatory)][string]$AgentFile,
        [string]$Manufacturer = 'Contoso',
        [string]$Model = 'RobotV1'
    )

    # 2>&1 and ToString(): everything the agent or dotnet writes comes back as text, so nothing goes to the error stream
    # (the notebook kernel marks a cell as failed when something is written there).
    $a = @('run', $AgentFile, '--',
        '--folder', $Folder, '--registration-id', $Device, '--id-scope', $IdScope, '--state', $State,
        '--manufacturer', $Manufacturer, '--model', $Model)
    dotnet @a 2>&1 | ForEach-Object { $_.ToString() }
}

function New-AdrGroup {
    <#
    .SYNOPSIS
    Creates an ADR group defined by a query on device properties.
    .DESCRIPTION
    The service accepts '*' or a single WHERE clause, for example
    "WHERE model = 'RobotV1' AND softwareRevision = '1.0.0'". The query cannot be changed after creation.
    A refused query is returned as the error text instead of throwing, so a notebook can try several syntaxes.
    .PARAMETER Name
    Group name (also used as display name).
    .PARAMETER Query
    The query string.
    .PARAMETER Namespace
    ADR namespace name.
    .PARAMETER ResourceGroup
    Resource group of the namespace.
    .OUTPUTS
    $null when the group was created; the error text when the service refused it.
    #>
    param(
        [Parameter(Mandatory)][string]$Name,
        [Parameter(Mandatory)][string]$Query,
        [Parameter(Mandatory)][string]$Namespace,
        [Parameter(Mandatory)][string]$ResourceGroup
    )

    # 2>&1 captures the error text in $r instead of letting it reach the notebook as an error.
    $r = az iot adr ns group create `
        --name $Name `
        --namespace $Namespace `
        --resource-group $ResourceGroup `
        --query-string $Query `
        --display-name $Name `
        -o json `
        --only-show-errors 2>&1

    # Refused (syntax, name, limits): hand the message back so the caller can show it or try another query.
    if ($LASTEXITCODE -ne 0) {
        return ($r | Out-String).Trim()
    }

    # Wait until the group is ready, so the next call (members, refresh) does not meet a half-created group.
    az iot adr ns group wait `
        --name $Name `
        --namespace $Namespace `
        --resource-group $ResourceGroup `
        --only-show-errors 2>&1 | Out-Null

    # $null = success.
    $null
}

function Remove-AdrGroup {
    <#
    .SYNOPSIS
    Deletes an ADR group (the devices stay).
    .PARAMETER Name
    Group name.
    .PARAMETER Namespace
    ADR namespace name.
    .PARAMETER ResourceGroup
    Resource group of the namespace.
    #>
    param(
        [Parameter(Mandatory)][string]$Name,
        [Parameter(Mandatory)][string]$Namespace,
        [Parameter(Mandatory)][string]$ResourceGroup
    )

    # --yes: no confirmation prompt (a notebook cannot answer it).
    # Output and errors are discarded on purpose: deleting a group that is already gone is not a problem
    # for the notebooks, which call this to start from a clean state.
    az iot adr ns group delete `
        --name $Name `
        --namespace $Namespace `
        --resource-group $ResourceGroup `
        --yes `
        --only-show-errors 2>&1 | Out-Null
}

function Revoke-AdrDeviceCertificates {
    <#
    .SYNOPSIS
    Revokes the certificates already issued to a device (ADR 'Revoke device certificates').
    .DESCRIPTION
    Existing certificates stop being accepted by the Hub at once, even if they have days of life left. The device itself
    stays enabled: with a valid bootstrap credential it registers again and receives a new certificate that the Hub accepts.
    To stop the device, disable it with Set-AdrDeviceEnablement.
    Works only for the authentication profile of type CertificateAuthoritySignedX509Certificate. Destructive for that device.
    .PARAMETER Name
    Device name.
    .PARAMETER Namespace
    ADR namespace name.
    .PARAMETER ResourceGroup
    Resource group of the namespace.
    .PARAMETER Profile
    Authentication profile name; 'default' unless the device has another.
    #>
    param(
        [Parameter(Mandatory)][string]$Name,
        [Parameter(Mandatory)][string]$Namespace,
        [Parameter(Mandatory)][string]$ResourceGroup,
        [string]$Profile = 'default'
    )

    # --yes: the command asks for confirmation, because the revocation cannot be undone.
    az iot adr ns device auth revoke-certs `
        --device-name $Name `
        --name $Profile `
        --namespace $Namespace `
        --resource-group $ResourceGroup `
        --yes `
        -o none `
        --only-show-errors
    Assert-Az "Revoca dei certificati di $Name"
}

function Set-AdrDeviceEnablement {
    <#
    .SYNOPSIS
    Enables or disables a device in the ADR namespace, and returns the state that ADR reports afterwards.
    .DESCRIPTION
    A disabled device cannot use even a valid certificate, and a new DPS registration fails (error 409000).
    That failure is written by az on stderr: run the registration with 2>$null in a notebook, or the kernel stops the cell.
    .PARAMETER Name
    Device name.
    .PARAMETER Namespace
    ADR namespace name.
    .PARAMETER ResourceGroup
    Resource group of the namespace.
    .PARAMETER State
    Enabled or Disabled.
    #>
    param(
        [Parameter(Mandatory)][string]$Name,
        [Parameter(Mandatory)][string]$Namespace,
        [Parameter(Mandatory)][string]$ResourceGroup,
        [Parameter(Mandatory)][ValidateSet('Enabled', 'Disabled')][string]$State
    )

    az iot adr ns device update `
        --name $Name `
        --namespace $Namespace `
        --resource-group $ResourceGroup `
        --enablement-state $State `
        -o none `
        --only-show-errors
    Assert-Az "Cambio di stato di $Name"

    # Read the state back from the service: the answer shows what ADR really holds, not what we asked for.
    Get-AdrDeviceState -Name $Name -Namespace $Namespace -ResourceGroup $ResourceGroup
}

function Set-AdrDeviceProperties {
    <#
    .SYNOPSIS
    Sets manufacturer, model and software revision of a device in the ADR namespace.
    .PARAMETER Name
    Device name (the registration id).
    .PARAMETER Namespace
    ADR namespace name.
    .PARAMETER ResourceGroup
    Resource group of the namespace.
    .PARAMETER Manufacturer
    Manufacturer; leave out to keep the current value.
    .PARAMETER Model
    Model; leave out to keep the current value.
    .PARAMETER SoftwareRevision
    Software revision; leave out to keep the current value. A software update changes this property.
    #>
    param(
        [Parameter(Mandatory)][string]$Name,
        [Parameter(Mandatory)][string]$Namespace,
        [Parameter(Mandatory)][string]$ResourceGroup,
        [string]$Manufacturer,
        [string]$Model,
        [string]$SoftwareRevision
    )

    # Build the argument list only with the properties that were given: an option left out is left unchanged by the service.
    $a = @()
    if ($Manufacturer)     { $a += '--manufacturer', $Manufacturer }
    if ($Model)            { $a += '--model', $Model }
    if ($SoftwareRevision) { $a += '--software-revision', $SoftwareRevision }

    # Nothing to set is a mistake of the caller, not a silent no-op.
    if (-not $a) {
        throw 'Set-AdrDeviceProperties: nessuna proprieta da impostare.'
    }

    # @a = splatting: the array becomes separate arguments of the command.
    az iot adr ns device update `
        --name $Name `
        --namespace $Namespace `
        --resource-group $ResourceGroup `
        @a `
        -o none `
        --only-show-errors
    Assert-Az "Aggiornamento delle proprieta di $Name"
}

function Start-DemoDevice {
    <#
    .SYNOPSIS
    Starts device\_run-device.ps1 for one device in its own PowerShell window.
    .DESCRIPTION
    The device keeps its state (key, certificate, log) in StateDir: a device that finds a valid certificate there does not
    register again, so move that folder away when the Azure environment is recreated. No secret goes on the command line:
    only paths and names. -ExecutionPolicy Bypass applies to that process only.
    .PARAMETER RunScript
    Full path of _run-device.ps1.
    .PARAMETER DeviceId
    Device id (the registration id).
    .PARAMETER StateDir
    The device's own state folder.
    .PARAMETER BootstrapCaDir
    Folder with the bootstrap CA of the device's enrollment group (created by the onboarding notebook).
    .PARAMETER DpsName
    DPS name.
    .PARAMETER ResourceGroup
    Resource group of the DPS.
    .PARAMETER IntervalSeconds
    Seconds between telemetry messages.
    .PARAMETER Count
    Number of messages before the device ends; 0 keeps it running until the window is closed.
    .PARAMETER Hidden
    No window: the output goes to stdout.log and stderr.log in StateDir.
    .OUTPUTS
    The started process.
    #>
    param(
        [Parameter(Mandatory)][string]$RunScript,
        [Parameter(Mandatory)][string]$DeviceId,
        [Parameter(Mandatory)][string]$StateDir,
        [Parameter(Mandatory)][string]$BootstrapCaDir,
        [Parameter(Mandatory)][string]$DpsName,
        [Parameter(Mandatory)][string]$ResourceGroup,
        [int]$IntervalSeconds = 5,
        [int]$Count = 0,
        [switch]$Hidden
    )

    New-Item -ItemType Directory -Force $StateDir | Out-Null

    # The device needs the bootstrap CA's private key to get its bootstrap certificate: without it, stop here with a clear message.
    if (-not (Test-Path (Join-Path $BootstrapCaDir 'ca-key.pem'))) {
        throw "Manca la CA di bootstrap in ${BootstrapCaDir}: esegui prima il notebook di onboarding."
    }

    # Arguments for the new pwsh process. -NoProfile = fast and predictable start; -ExecutionPolicy Bypass = this process only.
    $a = @(
        '-NoProfile',
        '-ExecutionPolicy', 'Bypass',
        '-File', $RunScript,
        '-DeviceId', $DeviceId,
        '-StateDir', $StateDir,
        '-BootstrapCaDir', $BootstrapCaDir,
        '-DpsName', $DpsName,
        '-ResourceGroup', $ResourceGroup,
        '-IntervalSeconds', $IntervalSeconds
    )
    if ($Count -gt 0) {
        $a += '-Count', $Count
    }

    # Quote the arguments that contain spaces (see Format-Arg).
    $argList = @($a | ForEach-Object { Format-Arg $_ })

    if ($Hidden) {
        # No window: a window-less process has nowhere to print, so its output goes to files in the device folder.
        Start-Process pwsh `
            -ArgumentList $argList `
            -PassThru `
            -WindowStyle Hidden `
            -RedirectStandardOutput (Join-Path $StateDir 'stdout.log') `
            -RedirectStandardError (Join-Path $StateDir 'stderr.log')
    }
    else {
        # -PassThru returns the process object, so the caller can wait for it or stop it.
        Start-Process pwsh -ArgumentList $argList -PassThru
    }
}

function Update-AdrGroup {
    <#
    .SYNOPSIS
    Asks ADR to recompute the membership of a group.
    .DESCRIPTION
    Allowed once per hour per group, even right after creation: a second call answers GroupRefreshRateLimited.
    .PARAMETER Name
    Group name.
    .PARAMETER Namespace
    ADR namespace name.
    .PARAMETER ResourceGroup
    Resource group of the namespace.
    .OUTPUTS
    $null when accepted; the error text when refused (for example the rate limit).
    #>
    param(
        [Parameter(Mandatory)][string]$Name,
        [Parameter(Mandatory)][string]$Namespace,
        [Parameter(Mandatory)][string]$ResourceGroup
    )

    # 2>&1 keeps the error text, so a refusal (rate limit) can be shown by the notebook instead of stopping it.
    $r = az iot adr ns group refresh `
        --name $Name `
        --namespace $Namespace `
        --resource-group $ResourceGroup `
        -o none `
        --only-show-errors 2>&1

    if ($LASTEXITCODE -ne 0) {
        return ($r | Out-String).Trim()
    }

    # $null = accepted.
    $null
}

# ===== Scenario ============================================================================================

function Get-DemoConfig {
    <#
    .SYNOPSIS
    Reads _scenario.psd1 and returns the scenario: resource names, devices and Fabric values.
    .DESCRIPTION
    _scenario.psd1 holds the values (workload, stage, instance, regions, groups, devices, Fabric ids); this function builds from them the
    resource names with the Microsoft naming convention <abbreviation>-<workload>-<environment>-<region>-<instance>, so a name is never
    written twice. The ADR namespace name accepts letters and hyphens only: the digits of the workload are dropped.
    It also silences the az CLI warnings, because the kernel would show anything written on stderr as an error.
    .PARAMETER Base
    The 'notebooks' folder, where _scenario.psd1 lives.
    .OUTPUTS
    An object with:
      Workload, Stage, Instance   the three values the names are built from
      Rg, RgRegion          resource group (one for the whole demo)
      AdrName, Adr          ADR namespace (Adr = Name, Region)
      Dps                   Name, Region, Link (the link name to ADR)
      EventGridName         the Event Grid namespace (MQTT broker) of the notebooks 20 and 21
      UpdateService         Name (Update Instance), Link (its name on the ADR namespace), Storage, Container: the Azure Update Service of the notebooks 14a-16
      Hubs                  array of IoT Hubs: Name, Region, Sku, Link, Group
      HubOf                 hashtable group name -> Hub name
      HubNames              the Hub names, in the order of the groups
      Fabric                WorkspaceId, EventstreamId, SourceId, EndpointUri, EntityPath
      Devices               array: Id, Group, Manufacturer, Model, SoftwareRevision
      CustomDevices         same fields: the devices of the notebooks 20-22 (Event Grid and the REST API), named after their purpose
      Groups, Allocation, Pki (Root, Issuing, Policy, ValidityDays)
      Out                   folder for keys, certificates and device state (private, never to be published)
    .EXAMPLE
    $cfg = Get-DemoConfig -Base 'D:\Dev\2026\IoTHub\WPC2026\notebooks'
    az iot hub show --name $cfg.HubOf.robots --resource-group $cfg.Rg
    #>
    param(
        [Parameter(Mandatory)][string]$Base
    )

    $file = Join-Path $Base '_scenario.psd1'
    if (-not (Test-Path $file)) {
        throw "Non trovo $file."
    }

    # A .psd1 is a PowerShell data file: loaded as data, nothing in it is executed.
    $s = Import-PowerShellDataFile $file

    # Only errors from az, no warnings: the kernel would show a warning on stderr as a failure.
    $env:AZURE_CORE_ONLY_SHOW_ERRORS = 'true'

    # The same for the Python warnings of the az extensions: the eventgrid extension prints SyntaxWarning lines on stderr the
    # first time it is compiled, and the kernel marks the cell as failed even though the command worked (seen on 2026-11-22).
    $env:PYTHONWARNINGS = 'ignore'

    # When a newer az is available, az tries to upgrade itself and asks "Do you want to continue? (Y/n)". A notebook cannot answer, so
    # az prints a traceback on stderr and the cell is marked as failed, whatever command it ran (seen on 2026-11-22 in notebook 20).
    # The variable name has a hyphen: it is the az config section 'auto-upgrade', key 'enable'. Upgrade az by hand, outside the notebooks.
    ${env:AZURE_AUTO-UPGRADE_ENABLE} = 'no'

    # Short names for the pieces of the naming convention: workload, stage (environment), instance, region code.
    $w = $s.Workload
    $st = $s.Stage
    $i = $s.Instance
    $rc = $s.RegionCode

    # One IoT Hub per group (fleet), numbered by the group's HubInstance. Link = the DPS-to-Hub link name used by ADR.
    $hubs = @($s.Groups | ForEach-Object {
        $n = "iot-$w-$st-$rc-$($_.HubInstance)"
        @{
            Name   = $n
            Region = $s.Region
            Sku    = $s.HubSku
            Link   = "adrlink-iot-$w-$st-$rc-$($_.HubInstance)"
            Group  = $_.Name
        }
    })

    # Group name -> Hub name, so a notebook can write $cfg.HubOf.robots.
    $hubOf = @{}
    foreach ($h in $hubs) {
        $hubOf[$h.Group] = $h.Name
    }

    [pscustomobject]@{
        Workload   = $w
        Stage      = $st
        Instance   = $i
        Rg         = "rg-$w-$st-$rc-$i"
        RgRegion   = $s.Region
        # The ADR namespace name accepts letters and hyphens only: digits are removed from the workload.
        AdrName    = "adrns-$($w -replace '[0-9]', '')-$st-$rc"
        Adr        = @{ Name = "adrns-$($w -replace '[0-9]', '')-$st-$rc"; Region = $s.Region }
        Dps        = @{ Name = "provs-$w-$st-$rc-$i"; Region = $s.Region; Link = "adrlink-provs-$w-$st-$rc-$i" }
        DpsName    = "provs-$w-$st-$rc-$i"
        # Event Grid namespace: the abbreviation of the Cloud Adoption Framework list is evgns.
        EventGridName = "evgns-$w-$st-$rc-$i"
        # Azure Update Service (Device Update, preview) of the notebooks 14a-16: the Update Instance, its link name on the ADR namespace,
        # and the storage account (lowercase letters and digits only, 3-24 characters) with the container that holds the update files.
        UpdateService = @{
            Name      = "adu-$w-$st-$rc-$i"
            Link      = 'primary-su'
            Storage   = "st$w$st$rc$i"
            Container = 'updates'
        }
        Hubs       = $hubs
        HubOf      = $hubOf
        HubNames   = @($hubs | ForEach-Object { $_.Name })
        Fabric     = $s.Fabric
        Devices    = @($s.Devices)
        CustomDevices = @($s.CustomDevices)
        Groups     = @($s.Groups)
        Allocation = $s.Allocation
        Pki        = @{
            Root         = "root-$w-$st"
            Issuing      = "ica-$w-$st"
            Policy       = "cp-$w-$st"
            ValidityDays = $s.PkiValidityDays
        }
        # Inside the project, next to the notebooks: it holds private keys and is ignored by git; it can be deleted at any time.
        Out        = [IO.Path]::GetFullPath((Join-Path $Base '..\artifacts'))
    }
}

function Get-ScenarioDir {
    <#
    .SYNOPSIS
    The state folder of a device: its key, certificate, log and history. The folder is named after the notebook that creates it.
    .DESCRIPTION
    Notebooks of the same story share the folder, so a later notebook continues from what the earlier one left. The path is
    <Out>\<notebook>\<device>, so a state folder can be traced back to the step that made it.
    The folder holds private keys: never publish it.
    .PARAMETER Config
    The object returned by Get-DemoConfig.
    .PARAMETER Notebook
    Name of the notebook that creates the device state, without extension (for example '21-device-registrazione').
    .PARAMETER DeviceId
    Device id (the registration id).
    .OUTPUTS
    The folder path (the folder is not created here).
    #>
    param(
        [Parameter(Mandatory)]$Config,
        [Parameter(Mandatory)][string]$Notebook,
        [Parameter(Mandatory)][string]$DeviceId
    )

    # Only builds the path (one place for the convention); the folder is created by whoever uses it (New-SimDevice).
    Join-Path $Config.Out "$Notebook\$DeviceId"
}

function Open-ScenarioDevice {
    <#
    .SYNOPSIS
    Opens a PowerShell device (device\Device.ps1) that talks to the real DPS, with its state in the folder of a notebook.
    .DESCRIPTION
    Needs device\Device.ps1 loaded (_start.ps1 does it). With -Fresh the notebook's folder for this device is moved away first
    (to <Out>\trash, never deleted), so the device starts with no certificate and registers as the first time; without it the
    device continues from its folder: key, certificate and the Hub it was assigned are read back.
    The bootstrap CA is the one of the device's enrollment group, created by the onboarding notebook.
    .PARAMETER Config
    The object returned by Get-DemoConfig.
    .PARAMETER DeviceId
    Device id; its group is read from the scenario.
    .PARAMETER Notebook
    The notebook whose folder holds the state of this device (see Get-ScenarioDir).
    .PARAMETER Fresh
    Start from an empty folder.
    .OUTPUTS
    The device object of Device.ps1 (use Invoke-DeviceTick, Invoke-DeviceRegistration, Get-DeviceCertStatus on it).
    #>
    param(
        [Parameter(Mandatory)]$Config,
        [Parameter(Mandatory)][string]$DeviceId,
        [Parameter(Mandatory)][string]$Notebook,
        [switch]$Fresh
    )

    # The device's group (fleet) comes from the scenario: it decides which bootstrap CA it uses.
    $group = ($Config.Devices | Where-Object { $_.Id -eq $DeviceId }).Group
    if (-not $group) {
        throw "Il device $DeviceId non e' nello scenario (_scenario.psd1)."
    }

    $dir  = Get-ScenarioDir -Config $Config -Notebook $Notebook -DeviceId $DeviceId
    $boot = Join-Path $Config.Out "bootstrap-ca-$group"
    if (-not (Test-Path (Join-Path $boot 'ca-key.pem'))) {
        throw "Manca la CA di bootstrap in ${boot}: esegui prima il notebook di onboarding."
    }

    # -Fresh: move the old state to <Out>\trash\ instead of deleting it (nothing is ever lost, as the rules of the project say).
    if ($Fresh -and (Test-Path $dir)) {
        $trash = Join-Path $Config.Out ('trash\' + $Notebook + '-' + $DeviceId + '-' + (Get-Date -Format 'yyyyMMdd-HHmmss'))
        New-Item -ItemType Directory -Force (Split-Path $trash) | Out-Null
        Move-Item $dir $trash
    }

    $dps = @{ Name = $Config.DpsName; Rg = $Config.Rg }

    # A device.log in the folder means the device already lived here: -Reuse makes it read back its credentials and its Hub.
    if (Test-Path (Join-Path $dir 'device.log')) {
        New-SimDevice -Id $DeviceId -Dir $dir -BootstrapCaDir $boot -Dps $dps -Reuse
    }
    else {
        New-SimDevice -Id $DeviceId -Dir $dir -BootstrapCaDir $boot -Dps $dps
    }
}

function Show-HubAcceptance {
    <#
    .SYNOPSIS
    Sends one test message to the device's Hub with the device certificate and prints what the Hub answers.
    .DESCRIPTION
    204 means the Hub accepts the certificate, 401 means it refuses it (revoked, device disabled, unknown CA).
    .PARAMETER Label
    What is being tested: it starts the printed line.
    .PARAMETER Hub
    Hub host name (xxx.azure-devices.net), or the Hub name.
    .PARAMETER DeviceId
    Device id the certificate belongs to.
    .PARAMETER StateDir
    Folder with the certificate (issued-chain.pem) and the key (device-key.pem).
    .OUTPUTS
    One line of text: the label, the HTTP status code and its meaning. For the bare code use Test-HubAcceptsCertificate.
    #>
    param(
        [Parameter(Mandatory)][string]$Label,
        [Parameter(Mandatory)][string]$Hub,
        [Parameter(Mandatory)][string]$DeviceId,
        [Parameter(Mandatory)][string]$StateDir
    )

    # A bare Hub name (no dot) gets the standard host suffix.
    if ($Hub -notmatch '\.') {
        $Hub = "$Hub.azure-devices.net"
    }

    $code = Test-HubAcceptsCertificate -Hub $Hub -DeviceId $DeviceId -StateDir $StateDir

    # The two answers the demo is about get a word; anything else is flagged, not hidden.
    $meaning = switch ($code) {
        204     { 'accettato' }
        401     { 'rifiutato' }
        default { 'risposta inattesa' }
    }

    # {0,-52} pads the label to 52 characters, so a list of lines lines up.
    '{0,-52} HTTP {1}  ({2})' -f $Label, $code, $meaning
}
